onGenerateAI:
{{
  (() => {

    q_ws_ai_generate.run({
      user_email:
        appsmith.store.userEmail || "",

      instruction:
        CW_Constructor.model.ai_instruction || ""
    })
    .then((data) => {

      const response =
        Array.isArray(data)
          ? (data[0] || {})
          : (data || {});

      storeValue(
        "wsAiResponseEnvelope",
        {
          nonce: Date.now(),
          response: response
        },
        false
      );

    })
    .catch((error) => {

      storeValue(
        "wsAiResponseEnvelope",
        {
          nonce: Date.now(),
          response: {
            ok: false,
            needs_clarification: true,
            clarification_question:
              "No fue posible generar la propuesta.",
            warnings: [
              String(
                error && error.message
                  ? error.message
                  : error || "Error desconocido"
              )
            ]
          }
        },
        false
      );

    });

  })()
}}

onRerunQuery:
{{
  (async () => {
    const queryId =
      CW_Constructor.model.selectedQueryId || "";

    const queryName =
      CW_Constructor.model.selectedQueryName || "";

    if (!queryId) {
      showAlert(
        "Selecciona una consulta antes de re-ejecutarla.",
        "warning"
      );

      return;
    }

    await storeValue(
      "selectedQueryId",
      queryId
    );

    await storeValue(
      "selectedQueryName",
      queryName
    );

    await JS_WS_QueryExecution.rerunSelectedQuery();
  })()
}}

onSelectQuery:
{{
  (() => {

    const selectedQueryId =
      String(
        CW_Constructor.model.selectedQueryId ||
        ""
      ).trim();

    if (!selectedQueryId) {
      showAlert(
        "No se pudo identificar la consulta seleccionada.",
        "error"
      );

      return;
    }

    return storeValue(
      "selectedQueryId",
      selectedQueryId
    )
      .then(() =>
        Promise.all([
          Q_DrawerPosts.run(),
          Q_DrawerActors.run()
        ])
      );

  })()
}}

onToggleQueryStatus:
{{
  (async () => {
    const queryId =
      CW_Constructor.model.selectedQueryId || "";

    const queryName =
      CW_Constructor.model.selectedQueryName || "";

    if (!queryId) {
      showAlert(
        "Selecciona una consulta antes de cambiar su estado.",
        "warning"
      );

      return;
    }

    await storeValue(
      "selectedQueryId",
      queryId
    );

    await storeValue(
      "selectedQueryName",
      queryName
    );

    await JS_WS_QueryExecution.toggleSelectedQueryStatus();
  })()
}}

srcDoc.css:
@charset "UTF-8";
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  min-height: 100%;
}

body {
  font-family: "DM Sans", sans-serif;
  background: transparent;
  color: #2F323B;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  color: inherit;
}

[hidden] {
  display: none !important;
}

.queries-shell {
  --ink: #2F323B;
  --ink-soft: #414650;
  --blue: #2972A9;
  --blue-dark: #245F8B;
  --cyan: #2E9BCB;
  --cyan-soft: #DFF3FB;
  --light-blue: #A7CDDE;
  --paper: #FFFFFF;
  --surface: #F7FAFC;
  --surface-strong: #F1F6F9;
  --line: rgba(167, 205, 222, 0.58);
  --line-soft: rgba(167, 205, 222, 0.30);
  --text: #2F323B;
  --muted: #717983;
  --muted-soft: #9299A1;
  --success: #2C9A75;
  --warning: #C79443;
  --danger: #A95C5C;
  width: 100%;
  min-height: 100%;
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  gap: 14px;
  padding: 8px;
  background: linear-gradient(180deg, #F8FBFD 0%, #FFFFFF 100%);
}

/* =========================================================
   NAVEGACIÓN INTERNA DE CONSULTAS
   ========================================================= */
.queries-sidebar {
  min-height: 680px;
  padding: 16px 10px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(247, 250, 252, 0.98), rgba(255, 255, 255, 0.98));
  box-shadow: 0 10px 24px rgba(47, 50, 59, 0.06);
}

.queries-sidebar-heading {
  padding: 5px 10px 16px;
  display: flex;
  flex-direction: column;
}

.queries-sidebar-heading span {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
}

.queries-sidebar-heading strong {
  margin-top: 4px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 18px;
}

.queries-nav {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.queries-nav-item {
  position: relative;
  width: 100%;
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 10px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  text-align: left;
  transition: color 0.2s, background 0.2s, transform 0.2s;
}

.queries-nav-item:hover {
  color: var(--blue);
  background: rgba(167, 205, 222, 0.14);
}

.queries-nav-item.active {
  color: var(--blue);
  background: linear-gradient(90deg, rgba(46, 155, 203, 0.15), rgba(167, 205, 222, 0.1));
}

.queries-nav-item.active::before {
  content: "";
  width: 3px;
  height: 30px;
  margin-left: -10px;
  border-radius: 0 4px 4px 0;
  background: linear-gradient(180deg, var(--blue), var(--cyan));
}

.queries-nav-icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.07);
  font-size: 14px;
  font-weight: 700;
}

.queries-nav-item.active .queries-nav-icon {
  background: rgba(46, 155, 203, 0.14);
}

.queries-nav-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.queries-nav-copy strong {
  color: inherit;
  font-size: 11px;
  font-weight: 700;
}

.queries-nav-copy small {
  margin-top: 2px;
  color: #969BA2;
  font-size: 8px;
}

/* =========================================================
   CONTENIDO DE CONSULTAS
   ========================================================= */
.queries-main {
  min-width: 0;
  padding: 4px 2px 14px;
}

.queries-header {
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 14px;
}

.queries-heading {
  min-width: 0;
}

.queries-kicker {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
}

.queries-heading h1 {
  margin-top: 3px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 27px;
  line-height: 1.1;
}

.queries-heading p {
  max-width: 720px;
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.queries-view {
  display: none;
}

.queries-view.active {
  display: block;
}

/* HEADER */
.constructor-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  margin-bottom: 18px;
  padding: 2px 4px 0;
}

.constructor-heading {
  min-width: 0;
  flex: 1;
}

.constructor-eyebrow {
  display: block;
  margin-bottom: 6px;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.constructor-heading h1 {
  margin-bottom: 7px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 29px;
  font-weight: 700;
  line-height: 1.15;
}

.constructor-heading p {
  max-width: 760px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.constructor-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-shrink: 0;
}

.new-query-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 142px;
  height: 42px;
  padding: 0 16px;
  border: 0;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(41, 114, 169, 0.18);
}

.new-query-button span {
  font-size: 16px;
}

/* SELECTOR */
.mode-selector {
  display: none;
  width: fit-content;
  margin: 0;
  padding: 4px;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
}

.mode-selector.visible {
  display: flex;
}

.mode-option {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 132px;
  min-height: 42px;
  padding: 6px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.mode-option.active {
  background: rgba(41, 114, 169, 0.09);
  color: var(--blue);
}

.mode-icon {
  width: 27px;
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 8px;
  background: rgba(167, 205, 222, 0.18);
  color: var(--blue);
  font-size: 12px;
  font-weight: 700;
}

.mode-copy {
  display: flex;
  flex-direction: column;
}

.mode-copy strong {
  font-size: 10.5px;
  font-weight: 700;
}

.mode-copy small {
  margin-top: 1px;
  color: var(--muted);
  font-size: 8px;
}

/* STEPPER */
.constructor-wizard {
  margin-bottom: 18px;
  padding: 14px 18px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.9);
}

.wizard-stepper {
  display: flex;
  align-items: center;
  width: 100%;
}

.wizard-step {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 128px;
  color: var(--muted);
}

.wizard-number {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #FFFFFF;
  font-size: 10px;
  font-weight: 800;
}

.wizard-step div {
  display: flex;
  flex-direction: column;
}

.wizard-step strong {
  font-size: 10.5px;
  font-weight: 700;
}

.wizard-step small {
  margin-top: 1px;
  color: var(--muted-soft);
  font-size: 8.5px;
}

.wizard-step.active .wizard-number {
  border-color: transparent;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
}

.wizard-step.active strong {
  color: var(--blue);
}

.wizard-step.completed .wizard-number {
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
}

.wizard-line {
  flex: 1;
  height: 1px;
  min-width: 20px;
  margin: 0 12px;
  background: var(--line);
}

.wizard-line.completed {
  background: rgba(41, 114, 169, 0.38);
}

/* MAIN */
.constructor-body {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(320px, 0.8fr);
  gap: 18px;
  align-items: start;
}

.constructor-main-view,
.constructor-library {
  min-width: 0;
}

/* HOME */
.constructor-home {
  min-height: 560px;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(247, 250, 252, 0.96));
}

.home-intro {
  max-width: 690px;
  margin-bottom: 26px;
}

.home-kicker {
  display: block;
  margin-bottom: 7px;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.home-intro h2 {
  margin-bottom: 8px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 26px;
}

.home-intro p {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.65;
}

.creation-mode-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.creation-card {
  min-height: 330px;
  display: flex;
  flex-direction: column;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: #FFFFFF;
  text-align: left;
  cursor: pointer;
}

.creation-card-icon {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  border-radius: 12px;
  background: rgba(41, 114, 169, 0.09);
  color: var(--blue);
  font-size: 18px;
}

.creation-card-heading span {
  display: block;
  margin-bottom: 4px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.creation-card-heading h3 {
  margin-bottom: 10px;
  font-family: "Playfair Display", serif;
  font-size: 23px;
}

.creation-card > p {
  min-height: 50px;
  margin-bottom: 18px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.6;
}

.creation-benefits {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-bottom: 22px;
}

.creation-benefits span {
  font-size: 10.5px;
}

.creation-card-action {
  display: flex;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 16px;
  border-top: 1px solid var(--line-soft);
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}

/* WIZARD */
.wizard-view {
  min-height: 560px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
}

.stage-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line-soft);
}

.stage-kicker {
  display: block;
  margin-bottom: 5px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.stage-header h2 {
  margin-bottom: 5px;
  font-family: "Playfair Display", serif;
  font-size: 22px;
}

.stage-header p {
  color: var(--muted);
  font-size: 11.5px;
}

.stage-badge {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
}

/* MANUAL PASO 1 */
.manual-rule-card {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 15px;
}

.manual-group-heading {
  grid-column: 1/-1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line-soft);
  background: rgba(167, 205, 222, 0.07);
}

.manual-group-heading span {
  display: block;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-group-heading strong {
  font-size: 12px;
}

.manual-logic-badge {
  width: 48px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 9px;
  font-weight: 800;
}

.manual-rule-row {
  min-width: 0;
  padding: 16px;
  border-right: 1px solid var(--line-soft);
}

.manual-rule-row:last-child {
  border-right: 0;
}

.manual-rule-copy {
  min-height: 76px;
}

.manual-rule-badge {
  display: inline-flex;
  margin-bottom: 7px;
  padding: 5px 8px;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 800;
}

.manual-rule-badge.include {
  color: var(--blue);
  background: rgba(41, 114, 169, 0.09);
}

.manual-rule-badge.and {
  color: #2582A7;
  background: rgba(46, 155, 203, 0.1);
}

.manual-rule-badge.exclude {
  color: #8E4E4E;
  background: rgba(169, 92, 92, 0.09);
}

.manual-rule-copy strong {
  display: block;
  margin-bottom: 4px;
  font-size: 11.5px;
}

.manual-rule-copy p {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.manual-term-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
}

.manual-term-input {
  width: 100%;
  min-width: 0;
  height: 38px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  outline: none;
  background: #FBFDFE;
  font-size: 10px;
}

.ai-instruction-input {
  height: 132px;
  min-height: 132px;
  padding: 10px 11px;
  line-height: 1.5;
  resize: vertical;
}

.manual-add-term {
  min-width: 70px;
  height: 38px;
  padding: 0 10px;
  border: 1px solid rgba(41, 114, 169, 0.18);
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.07);
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  cursor: pointer;
}

.manual-term-list {
  min-height: 42px;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 6px;
  margin-top: 7px;
  padding: 7px;
  border-radius: 9px;
  background: rgba(167, 205, 222, 0.07);
}

.manual-empty-terms {
  color: var(--muted-soft);
  font-size: 9px;
}

.manual-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 0 5px 0 9px;
  border-radius: 8px;
  color: var(--blue);
  background: rgba(41, 114, 169, 0.1);
  font-size: 10px;
  font-weight: 600;
}

.manual-chip-remove {
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
}

.manual-group-footer {
  padding-top: 10px;
}

.manual-add-group {
  width: 100%;
  height: 38px;
  border: 1px dashed rgba(41, 114, 169, 0.35);
  border-radius: 9px;
  background: transparent;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.manual-stage-summary,
.manual-source-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  background: rgba(167, 205, 222, 0.06);
  font-size: 10px;
}

.manual-stage-summary strong,
.manual-source-summary strong {
  color: var(--blue);
}

/* MANUAL PASO 2 */
.manual-sources-section,
.manual-web-section {
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(180deg, #FFFFFF, #FBFDFE);
}

.manual-web-section {
  margin-top: 12px;
}

.manual-sources-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.manual-sources-heading span {
  display: block;
  margin-bottom: 2px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-sources-heading strong {
  display: block;
  font-size: 12px;
}

.manual-sources-heading small {
  color: var(--muted);
  font-size: 9px;
}

.manual-source-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.manual-web-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
}

.manual-source-card {
  position: relative;
  min-height: 94px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #FFFFFF;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.manual-source-card:hover {
  border-color: rgba(41, 114, 169, 0.36);
}

.manual-source-card.selected {
  border-color: rgba(41, 114, 169, 0.62);
  background: rgba(41, 114, 169, 0.055);
  box-shadow: 0 0 0 2px rgba(41, 114, 169, 0.05);
}

.manual-source-card.unavailable {
  opacity: 0.48;
  cursor: default;
}

.manual-source-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 14px;
  font-weight: 800;
}

.manual-source-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.manual-source-platform {
  margin-bottom: 2px;
  color: var(--blue);
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-source-content strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.manual-source-status,
.manual-source-description {
  margin-top: 4px;
  color: var(--muted);
  font-size: 9px;
}

.manual-status-dot {
  width: 6px;
  height: 6px;
  display: inline-block;
  margin-right: 4px;
  border-radius: 50%;
}

.manual-status-dot.active {
  background: var(--success);
}

.manual-status-dot.inactive {
  background: var(--muted-soft);
}

.manual-source-check {
  width: 23px;
  height: 23px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #FFFFFF;
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 800;
}

.manual-source-card.selected .manual-source-check {
  border-color: var(--blue);
  background: var(--blue);
}

.manual-source-switch {
  width: 40px;
  height: 23px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding: 2px;
  border-radius: 999px;
  background: rgba(113, 121, 131, 0.2);
  transition: background 0.18s ease;
}

.manual-source-switch span {
  width: 19px;
  height: 19px;
  display: block;
  border-radius: 50%;
  background: #FFFFFF;
  box-shadow: 0 2px 4px rgba(47, 50, 59, 0.12);
  transition: transform 0.18s ease;
}

.manual-source-switch.active {
  background: linear-gradient(135deg, var(--blue), var(--cyan));
}

.manual-source-switch.active span {
  transform: translateX(17px);
}

.manual-source-empty {
  grid-column: 1/-1;
  min-height: 100px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 20px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  text-align: center;
}

.manual-source-empty strong {
  margin-bottom: 4px;
  font-size: 11px;
}

.manual-source-empty span {
  color: var(--muted);
  font-size: 9px;
}

.manual-source-summary > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.manual-source-summary-icon {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(44, 154, 117, 0.1);
  color: var(--success);
  font-weight: 800;
}

/* ACTIONS */
.stage-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line-soft);
}

.stage-actions-right {
  display: flex;
  gap: 8px;
}

.stage-button {
  min-width: 120px;
  height: 40px;
  padding: 0 15px;
  border-radius: 10px;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
}

.stage-button.secondary {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--blue);
}

.stage-button.primary {
  border: 0;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
}

.stage-button:disabled {
  opacity: 0.45;
  cursor: default;
}

/* LIBRARY */
.constructor-library {
  position: static;
  top: auto;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.95);
}

.library-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 15px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line-soft);
}

.library-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.library-heading h2 {
  margin-bottom: 4px;
  font-family: "Playfair Display", serif;
  font-size: 19px;
}

.library-heading p {
  color: var(--muted);
  font-size: 10px;
}

.library-count {
  min-width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
}

.query-library-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 340px));
  justify-content: start;
  align-items: stretch;
  gap: 14px;
  min-height: 300px;
}

.saved-query-card {
  width: 100%;
  min-width: 0;
  min-height: 248px;
  display: flex;
  flex-direction: column;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: linear-gradient(180deg, #FFFFFF 0%, #FBFDFE 100%);
  box-shadow: 0 8px 20px rgba(47, 50, 59, 0.045);
  cursor: pointer;
  transition: border-color 0.18s, box-shadow 0.18s, transform 0.18s, background 0.18s;
}

.saved-query-card:hover {
  transform: translateY(-2px);
  border-color: rgba(46, 155, 203, 0.48);
  box-shadow: 0 12px 26px rgba(47, 50, 59, 0.075);
}

.saved-query-card[aria-pressed=true] {
  border-color: rgba(46, 155, 203, 0.62);
  background: linear-gradient(180deg, #FFFFFF 0%, rgba(223, 243, 251, 0.34) 100%);
  box-shadow: 0 10px 24px rgba(41, 114, 169, 0.09);
}

.saved-query-card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 11px;
}

.saved-query-title {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.saved-query-title strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.saved-query-title span {
  margin-top: 2px;
  color: var(--muted-soft);
  font-size: 10px;
}

.saved-query-status {
  height: 21px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
}

.saved-query-status.active {
  color: #23775C;
  background: rgba(44, 154, 117, 0.1);
}

.saved-query-status.inactive {
  color: #777D85;
  background: rgba(115, 121, 130, 0.08);
}

.saved-query-formula {
  min-height: 70px;
  max-height: 70px;
  display: -webkit-box;
  overflow: hidden;
  margin-bottom: 11px;
  padding: 9px 10px;
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background: rgba(167, 205, 222, 0.08);
  color: var(--ink-soft);
  font-family: monospace;
  font-size: 10.5px;
  line-height: 1.5;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.saved-query-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-top: auto;
  margin-bottom: 10px;
}

.saved-query-metrics span {
  min-width: 0;
  padding: 7px 4px;
  border-radius: 8px;
  background: var(--surface);
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.25;
  text-align: center;
}

.saved-query-metrics strong {
  display: block;
  margin-bottom: 1px;
  color: var(--blue);
  font-size: 13px;
}

.saved-query-footer {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 9px;
  border-top: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 10.5px;
}

.saved-query-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

.saved-query-actions .stage-button {
  min-width: 0;
  height: 30px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 10.5px;
}

.saved-query-actions .saved-query-status {
  height: 20px;
  padding: 3px 7px;
  font-size: 9.5px;
}

.library-empty {
  grid-column: 1/-1;
}

.library-empty {
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border: 1px dashed var(--line);
  border-radius: 12px;
  text-align: center;
}

.empty-pulse {
  width: 38px;
  height: 38px;
  margin-bottom: 12px;
  border-radius: 11px;
  background: rgba(41, 114, 169, 0.1);
}

.library-empty strong {
  margin-bottom: 4px;
  font-size: 11px;
}

.library-empty span {
  color: var(--muted);
  font-size: 9px;
}

.library-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
}

.library-pagination button {
  width: 31px;
  height: 31px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #FFFFFF;
  color: var(--blue);
}

.library-pagination button:disabled {
  opacity: 0.35;
}

.library-pagination span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
}

/* =========================================================
   FUENTES
   ========================================================= */
.sources-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
}

.sources-panel {
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 8px 22px rgba(47, 50, 59, 0.045);
}

.sources-panel-heading,
.sources-list-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 15px;
}

.sources-panel-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.sources-panel-heading h2,
.sources-list-header h2 {
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 19px;
}

.sources-panel-heading p,
.sources-list-header p {
  max-width: 680px;
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.sources-count {
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 0 8px;
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
}

.sources-form {
  display: grid;
  grid-template-columns: minmax(150px, 0.75fr) minmax(180px, 1fr) minmax(200px, 1.1fr) auto;
  gap: 10px;
  align-items: end;
}

.sources-field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sources-field > span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sources-control {
  width: 100%;
  height: 40px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: 0;
  background: #FBFDFE;
  color: var(--ink);
  font-size: 10px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.sources-control:focus {
  border-color: rgba(41, 114, 169, 0.58);
  background: #FFFFFF;
  box-shadow: 0 0 0 3px rgba(41, 114, 169, 0.07);
}

.sources-create-button {
  min-width: 140px;
  height: 40px;
  padding: 0 15px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 7px 16px rgba(41, 114, 169, 0.14);
}

.sources-create-button:hover {
  background: linear-gradient(135deg, var(--blue-dark), var(--blue));
}

.sources-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(150px, 210px) minmax(135px, 180px);
  gap: 8px;
  margin-bottom: 12px;
}

.sources-search {
  min-width: 0;
  height: 39px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #FFFFFF;
}

.sources-search > span {
  flex-shrink: 0;
  color: var(--blue);
  font-size: 13px;
}

.sources-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 10px;
}

.sources-search input::placeholder {
  color: var(--muted-soft);
}

.sources-filter {
  width: 100%;
  height: 39px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: 0;
  background: #FFFFFF;
  color: var(--ink);
  font-size: 9.5px;
  font-weight: 600;
  cursor: pointer;
}

.sources-table-wrap {
  min-width: 0;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: #FFFFFF;
}

.sources-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10px;
}

.sources-table th {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  background: rgba(167, 205, 222, 0.07);
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.sources-table td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--line-soft);
  color: var(--ink);
  vertical-align: middle;
}

.sources-table tbody tr:last-child td {
  border-bottom: 0;
}

.sources-table tbody tr:hover {
  background: rgba(167, 205, 222, 0.07);
}

.sources-platform {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--blue);
  font-weight: 700;
}

.sources-platform-icon {
  width: 27px;
  height: 27px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 8px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
}

.sources-handle {
  font-weight: 700;
}

.sources-external-id,
.sources-created {
  color: var(--muted);
  font-size: 9px;
}

.sources-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 23px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 700;
}

.sources-status::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.sources-status.active {
  color: #23775C;
  background: rgba(44, 154, 117, 0.1);
}

.sources-status.inactive {
  color: #777D85;
  background: rgba(115, 121, 130, 0.08);
}

.sources-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
}

.sources-action-button {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #FFFFFF;
  color: var(--blue);
  font-size: 8.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}

.sources-action-button:hover {
  border-color: rgba(41, 114, 169, 0.42);
  background: rgba(41, 114, 169, 0.05);
}

.sources-action-button.danger {
  color: var(--danger);
}

.sources-action-button.danger:hover {
  border-color: rgba(169, 92, 92, 0.36);
  background: rgba(169, 92, 92, 0.05);
}

.sources-empty {
  min-height: 220px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
}

.sources-empty strong {
  color: var(--ink);
  font-size: 11px;
}

.sources-empty span {
  max-width: 360px;
  margin-top: 5px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.55;
}

.sources-pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin-top: 12px;
}

.sources-pagination button {
  width: 31px;
  height: 31px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #FFFFFF;
  color: var(--blue);
  cursor: pointer;
}

.sources-pagination button:disabled {
  opacity: 0.35;
  cursor: default;
}

.sources-pagination span {
  min-width: 76px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
  text-align: center;
}

/* RESPONSIVE */
@media (max-width: 1180px) {
  .queries-shell {
    grid-template-columns: 76px minmax(0, 1fr);
  }
  .queries-sidebar-heading {
    display: none;
  }
  .queries-nav-copy {
    display: none;
  }
  .queries-nav-item {
    justify-content: center;
  }
  .queries-nav-item.active::before {
    position: absolute;
    left: 0;
    margin-left: 0;
  }
  .sources-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sources-create-button {
    width: 100%;
  }
}
@media (max-width: 900px) {
  .sources-toolbar {
    grid-template-columns: 1fr repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 780px) {
  .queries-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .sources-form,
  .sources-toolbar {
    grid-template-columns: 1fr;
  }
  .sources-create-button {
    width: 100%;
  }
}
@media (max-width: 560px) {
  .queries-shell {
    grid-template-columns: 64px minmax(0, 1fr);
    gap: 8px;
    padding: 5px;
  }
  .queries-sidebar {
    padding: 12px 6px;
  }
  .queries-nav-item {
    min-height: 48px;
    padding: 7px 5px;
  }
  .queries-nav-icon {
    width: 26px;
    height: 26px;
  }
  .queries-heading h1 {
    font-size: 24px;
  }
  .sources-panel {
    padding: 14px;
  }
}
@media (max-width: 1180px) {
  .constructor-actions {
    flex-direction: column;
    align-items: stretch;
  }
}
@media (max-width: 1120px) {
  .constructor-body {
    grid-template-columns: 1fr;
  }
  .constructor-library {
    position: static;
  }
}
@media (max-width: 900px) {
  .query-library-list {
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  }
  .manual-rule-card {
    grid-template-columns: 1fr;
  }
  .manual-rule-row {
    border-right: 0;
    border-bottom: 1px solid var(--line-soft);
  }
  .manual-source-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 820px) {
  .constructor-top {
    flex-direction: column;
  }
  .constructor-actions {
    width: 100%;
  }
  .mode-selector {
    width: 100%;
  }
  .mode-option {
    flex: 1;
  }
  .creation-mode-grid {
    grid-template-columns: 1fr;
  }
  .wizard-stepper {
    overflow-x: auto;
  }
}
@media (max-width: 560px) {
  .queries-shell {
    padding: 10px 5px 22px;
  }
  .query-library-list {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .saved-query-card {
    min-height: 0;
  }
  .saved-query-footer {
    align-items: flex-start;
    flex-direction: column;
  }
  .saved-query-actions {
    width: 100%;
    justify-content: flex-start;
  }
  .constructor-heading h1 {
    font-size: 25px;
  }
  .mode-selector {
    flex-direction: column;
  }
  .manual-source-grid {
    grid-template-columns: 1fr;
  }
  .manual-term-entry {
    grid-template-columns: 1fr;
  }
  .stage-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .stage-button {
    width: 100%;
  }
}
/* =========================================================
   DRAWER DE RESULTADOS DE CONSULTA
   ========================================================= */
body.query-drawer-open {
  overflow: hidden;
}

.query-drawer-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
  overflow: hidden;
}

.query-drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: rgba(28, 35, 48, 0.46);
  backdrop-filter: blur(2px);
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.24s ease;
}

.query-drawer {
  position: relative;
  z-index: 1;
  width: min(84%, 1420px);
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-left: 1px solid rgba(167, 205, 222, 0.82);
  background: linear-gradient(180deg, #F8FBFD 0%, #F4F8FB 52%, #F8FBFD 100%);
  box-shadow: -26px 0 64px rgba(24, 37, 51, 0.24);
  transform: translateX(100%);
  transition: transform 0.24s ease;
}

.query-drawer-overlay.open .query-drawer-backdrop {
  opacity: 1;
}

.query-drawer-overlay.open .query-drawer {
  transform: translateX(0);
}

/* HEADER */
.query-drawer-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 90px;
  padding: 16px 22px 14px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.44);
  background: rgba(255, 255, 255, 0.985);
}

.query-drawer-heading {
  min-width: 0;
  flex: 1;
}

.query-drawer-heading-topline {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.query-drawer-kicker {
  color: var(--cyan);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.query-drawer-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 21px;
  padding: 0 8px;
  border: 1px solid rgba(44, 154, 117, 0.16);
  border-radius: 999px;
  background: rgba(44, 154, 117, 0.09);
  color: var(--success);
  font-size: 7.5px;
  font-weight: 800;
}

.query-drawer-status::before {
  content: "";
  width: 5px;
  height: 5px;
  margin-right: 5px;
  border-radius: 50%;
  background: currentColor;
}

.query-drawer-status.inactive {
  border-color: rgba(169, 92, 92, 0.16);
  background: rgba(169, 92, 92, 0.08);
  color: var(--danger);
}

.query-drawer-title-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.query-drawer-query-mark {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid rgba(46, 155, 203, 0.18);
  border-radius: 10px;
  background: linear-gradient(145deg, rgba(41, 114, 169, 0.1), rgba(46, 155, 203, 0.13));
  color: var(--blue);
  font-size: 14px;
  font-weight: 800;
}

.query-drawer-title-copy {
  min-width: 0;
}

.query-drawer-title-row h2 {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 23px;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-title-copy p {
  max-width: 760px;
  margin-top: 4px;
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-close {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid rgba(167, 205, 222, 0.58);
  border-radius: 10px;
  background: #FFFFFF;
  color: var(--ink-soft);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s, background 0.2s, transform 0.2s;
}

.query-drawer-close:hover {
  border-color: rgba(41, 114, 169, 0.42);
  background: rgba(41, 114, 169, 0.06);
  color: var(--blue);
  transform: translateY(-1px);
}

/* COMMAND BAR */
.query-drawer-commandbar {
  flex-shrink: 0;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 7px 22px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.34);
  background: rgba(247, 250, 252, 0.96);
}

.query-drawer-range-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 0 9px;
  border: 1px solid rgba(167, 205, 222, 0.52);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.84);
  color: var(--muted);
  font-size: 8px;
  font-weight: 650;
}

.query-drawer-range-chip > span:first-child {
  color: var(--blue);
  font-size: 11px;
}

.query-drawer-command-note {
  color: var(--muted-soft);
  font-size: 7.5px;
  font-weight: 650;
}

/* TAB CONTROLS */
.query-drawer-tab-control {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.query-drawer-tabs {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 1px;
  overflow-x: auto;
  padding: 7px 18px 6px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.42);
  background: #FFFFFF;
  scrollbar-width: thin;
}

.query-drawer-tab {
  position: relative;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  flex-shrink: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 700;
  cursor: pointer;
  user-select: none;
  transition: color 0.18s, background 0.18s;
}

.query-drawer-tab::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: -7px;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--blue), var(--cyan));
  opacity: 0;
  transform: scaleX(0.55);
  transition: opacity 0.18s, transform 0.18s;
}

.query-drawer-tab:hover {
  background: rgba(167, 205, 222, 0.1);
  color: var(--blue);
}

.query-drawer-tab-icon {
  width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: currentColor;
  font-size: 9px;
  line-height: 1;
}

#queryDrawerTab-live:checked ~ .query-drawer-tabs label[for=queryDrawerTab-live],
#queryDrawerTab-what:checked ~ .query-drawer-tabs label[for=queryDrawerTab-what],
#queryDrawerTab-when:checked ~ .query-drawer-tabs label[for=queryDrawerTab-when],
#queryDrawerTab-howmuch:checked ~ .query-drawer-tabs label[for=queryDrawerTab-howmuch],
#queryDrawerTab-how:checked ~ .query-drawer-tabs label[for=queryDrawerTab-how],
#queryDrawerTab-who:checked ~ .query-drawer-tabs label[for=queryDrawerTab-who],
#queryDrawerTab-where:checked ~ .query-drawer-tabs label[for=queryDrawerTab-where],
#queryDrawerTab-profiles:checked ~ .query-drawer-tabs label[for=queryDrawerTab-profiles],
#queryDrawerTab-botometer:checked ~ .query-drawer-tabs label[for=queryDrawerTab-botometer],
#queryDrawerTab-streams:checked ~ .query-drawer-tabs label[for=queryDrawerTab-streams] {
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
}

#queryDrawerTab-live:checked ~ .query-drawer-tabs label[for=queryDrawerTab-live]::after,
#queryDrawerTab-what:checked ~ .query-drawer-tabs label[for=queryDrawerTab-what]::after,
#queryDrawerTab-when:checked ~ .query-drawer-tabs label[for=queryDrawerTab-when]::after,
#queryDrawerTab-howmuch:checked ~ .query-drawer-tabs label[for=queryDrawerTab-howmuch]::after,
#queryDrawerTab-how:checked ~ .query-drawer-tabs label[for=queryDrawerTab-how]::after,
#queryDrawerTab-who:checked ~ .query-drawer-tabs label[for=queryDrawerTab-who]::after,
#queryDrawerTab-where:checked ~ .query-drawer-tabs label[for=queryDrawerTab-where]::after,
#queryDrawerTab-profiles:checked ~ .query-drawer-tabs label[for=queryDrawerTab-profiles]::after,
#queryDrawerTab-botometer:checked ~ .query-drawer-tabs label[for=queryDrawerTab-botometer]::after,
#queryDrawerTab-streams:checked ~ .query-drawer-tabs label[for=queryDrawerTab-streams]::after {
  opacity: 1;
  transform: scaleX(1);
}

.query-drawer-tab-control:focus-visible ~ .query-drawer-tabs .query-drawer-tab {
  outline: none;
}

#queryDrawerTab-live:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-live],
#queryDrawerTab-what:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-what],
#queryDrawerTab-when:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-when],
#queryDrawerTab-howmuch:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-howmuch],
#queryDrawerTab-how:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-how],
#queryDrawerTab-who:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-who],
#queryDrawerTab-where:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-where],
#queryDrawerTab-profiles:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-profiles],
#queryDrawerTab-botometer:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-botometer],
#queryDrawerTab-streams:focus-visible ~ .query-drawer-tabs label[for=queryDrawerTab-streams] {
  box-shadow: 0 0 0 2px rgba(46, 155, 203, 0.24);
}

/* CONTENT */
.query-drawer-content {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 14px 16px 22px;
}

.query-drawer-section {
  display: none;
}

#queryDrawerTab-live:checked ~ .query-drawer-content [data-drawer-section-panel=live],
#queryDrawerTab-what:checked ~ .query-drawer-content [data-drawer-section-panel=what],
#queryDrawerTab-when:checked ~ .query-drawer-content [data-drawer-section-panel=when],
#queryDrawerTab-howmuch:checked ~ .query-drawer-content [data-drawer-section-panel=howmuch],
#queryDrawerTab-how:checked ~ .query-drawer-content [data-drawer-section-panel=how],
#queryDrawerTab-who:checked ~ .query-drawer-content [data-drawer-section-panel=who],
#queryDrawerTab-where:checked ~ .query-drawer-content [data-drawer-section-panel=where],
#queryDrawerTab-profiles:checked ~ .query-drawer-content [data-drawer-section-panel=profiles],
#queryDrawerTab-botometer:checked ~ .query-drawer-content [data-drawer-section-panel=botometer],
#queryDrawerTab-streams:checked ~ .query-drawer-content [data-drawer-section-panel=streams] {
  display: block;
}

.query-drawer-live-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(285px, 0.78fr);
  gap: 12px;
  align-items: start;
}

.query-drawer-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(167, 205, 222, 0.46);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 6px 18px rgba(47, 50, 59, 0.035);
}

.query-drawer-panel-header {
  min-height: 64px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px 11px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.28);
  background: linear-gradient(180deg, rgba(248, 251, 253, 0.96), rgba(255, 255, 255, 0.96));
}

.query-drawer-panel-header.compact {
  min-height: 52px;
  align-items: center;
  padding: 10px 12px;
}

.query-drawer-panel-kicker {
  display: block;
  margin-bottom: 3px;
  color: var(--cyan);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.query-drawer-panel-header h3 {
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
}

.query-drawer-panel-header p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 8.5px;
  line-height: 1.45;
}

.query-drawer-panel-info {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(167, 205, 222, 0.64);
  border-radius: 50%;
  color: var(--muted-soft);
  font-size: 8px;
  font-weight: 800;
}

/* LIVE FEED */
.query-drawer-feed-panel {
  min-height: 520px;
}

.query-drawer-feed-toolbar {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 12px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.22);
  background: rgba(247, 250, 252, 0.62);
}

.query-drawer-feed-filter {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 0 8px;
  border-radius: 7px;
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 700;
}

.query-drawer-feed-filter.active {
  background: linear-gradient(135deg, rgba(41, 114, 169, 0.1), rgba(46, 155, 203, 0.09));
  color: var(--blue);
}

.query-drawer-posts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  padding: 10px;
}

.query-drawer-post {
  min-width: 0;
  min-height: 178px;
  display: flex;
  flex-direction: column;
  padding: 12px;
  border: 1px solid rgba(167, 205, 222, 0.42);
  border-radius: 12px;
  background: #FFFFFF;
  box-shadow: 0 5px 12px rgba(47, 50, 59, 0.025);
  transition: border-color 0.18s, box-shadow 0.18s, transform 0.18s;
}

.query-drawer-post:hover {
  border-color: rgba(41, 114, 169, 0.28);
  box-shadow: 0 8px 18px rgba(47, 50, 59, 0.055);
  transform: translateY(-1px);
}

.query-drawer-post-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.query-drawer-post-source {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
}

.query-drawer-post-platform {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 8px;
  flex-shrink: 0;
  border-radius: 7px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.query-drawer-post-handle {
  min-width: 0;
  max-width: 150px;
  overflow: hidden;
  color: var(--ink-soft);
  font-size: 8px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-post-date {
  flex-shrink: 0;
  color: var(--muted-soft);
  font-size: 7px;
  font-weight: 650;
}

.query-drawer-post-copy {
  display: -webkit-box;
  margin-top: 10px;
  overflow: hidden;
  color: #3D424B;
  font-size: 9px;
  line-height: 1.55;
  word-break: break-word;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 5;
}

.query-drawer-post-copy > span {
  color: var(--muted-soft);
}

.query-drawer-post-footer {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid rgba(167, 205, 222, 0.22);
}

.query-drawer-post-metrics {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
}

.query-drawer-metric {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 6px;
  border-radius: 6px;
  background: rgba(167, 205, 222, 0.1);
  color: var(--muted);
  font-size: 6.7px;
  font-weight: 600;
}

.query-drawer-metric strong {
  color: var(--ink-soft);
  font-size: 7.2px;
  font-weight: 800;
}

.query-drawer-metric:nth-child(5) {
  font-size: 0;
}

.query-drawer-metric:nth-child(5)::before {
  content: "Persistidos";
  color: var(--muted);
  font-size: 6.7px;
  font-weight: 600;
}

.query-drawer-metric:nth-child(5) strong {
  margin-left: 3px;
}

.query-drawer-post-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 25px;
  padding: 0 8px;
  flex-shrink: 0;
  border: 1px solid rgba(41, 114, 169, 0.14);
  border-radius: 7px;
  background: rgba(41, 114, 169, 0.055);
  color: var(--blue);
  font-size: 7.5px;
  font-weight: 750;
  text-decoration: none;
}

.query-drawer-post-link:hover {
  border-color: rgba(41, 114, 169, 0.28);
  background: rgba(41, 114, 169, 0.09);
}

/* LIVE ANALYTICS */
.query-drawer-live-side {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.query-drawer-kpi-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);
  gap: 8px;
}

.query-drawer-kpi-card {
  min-width: 0;
  min-height: 96px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 11px;
  border: 1px solid rgba(167, 205, 222, 0.44);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.99), rgba(247, 250, 252, 0.98));
  box-shadow: 0 5px 14px rgba(47, 50, 59, 0.03);
}

.query-drawer-kpi-icon {
  width: 27px;
  height: 27px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 8px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
}

.query-drawer-kpi-card > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.query-drawer-kpi-card small {
  color: var(--muted-soft);
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.query-drawer-kpi-card strong {
  margin-top: 6px;
  overflow: hidden;
  color: var(--ink);
  font-size: 18px;
  line-height: 1.1;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-kpi-card-wide strong {
  font-size: 10px;
  line-height: 1.35;
  white-space: normal;
}

.query-drawer-kpi-card > div > span {
  margin-top: 5px;
  color: var(--muted);
  font-size: 6.9px;
  line-height: 1.35;
}

.query-drawer-platform-counts {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.query-drawer-platform-counts-panel {
  justify-content: flex-start;
  gap: 6px;
  min-height: 118px;
  padding: 12px;
}

.query-drawer-platform-pill {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 9px;
  border: 1px solid rgba(41, 114, 169, 0.12);
  border-radius: 999px;
  background: rgba(41, 114, 169, 0.065);
  color: var(--blue);
  font-size: 7.5px;
  font-weight: 750;
}

.query-drawer-context-copy {
  padding: 12px;
}

.query-drawer-context-copy p {
  color: var(--ink-soft);
  font-size: 8.5px;
  line-height: 1.55;
}

.query-drawer-context-copy span {
  display: block;
  margin-top: 8px;
  padding: 8px 9px;
  border-radius: 8px;
  background: rgba(46, 155, 203, 0.07);
  color: var(--muted);
  font-size: 7.5px;
  line-height: 1.5;
}

/* EMPTY / PLACEHOLDERS */
.query-drawer-empty {
  grid-column: 1/-1;
  min-height: 250px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 28px;
  border: 1px dashed rgba(167, 205, 222, 0.72);
  border-radius: 12px;
  background: rgba(247, 250, 252, 0.66);
  text-align: center;
}

.query-drawer-empty-icon,
.query-drawer-placeholder-icon {
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 3px;
  border-radius: 11px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 15px;
  font-weight: 800;
}

.query-drawer-empty strong {
  color: var(--ink-soft);
  font-size: 10px;
  font-weight: 800;
}

.query-drawer-empty > span:not(.query-drawer-empty-icon) {
  max-width: 360px;
  color: var(--muted-soft);
  font-size: 8.5px;
  line-height: 1.5;
}

.query-drawer-placeholder {
  min-height: 420px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 42px;
  border: 1px solid rgba(167, 205, 222, 0.46);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(247, 250, 252, 0.94));
