/* =========================================================
   DRAWER — AJUSTE VISUAL V2
   Más ancho + feed En vivo a 1 columna + Publicaciones en
   composición editorial de 2 columnas sin huecos de grid.
   ========================================================= */
/* Drawer más amplio en escritorio. */
.query-drawer {
  width: min(96vw, 1760px) !important;
}

/* En vivo: prioriza lectura de la publicación. */
.query-drawer-live-grid {
  grid-template-columns: minmax(0, 1.48fr) minmax(360px, 0.72fr);
  gap: 16px;
}

.query-drawer-posts {
  grid-template-columns: 1fr !important;
  gap: 18px !important;
  padding: 16px !important;
}

/* ¿Qué? > Publicaciones: dos columnas editoriales independientes.
   Multi-column evita los huecos verticales que producía CSS Grid
   cuando una tarjeta Web era mucho más corta que una social. */
.drawer-native-feed-grid {
  display: block;
  column-count: 2;
  column-gap: 18px;
  margin-top: 14px;
}

.drawer-native-feed-grid > .native-post-card {
  width: 100%;
  margin: 0 0 18px;
  break-inside: avoid;
  page-break-inside: avoid;
}

/* Cabecera más estable: fecha y tipo no compiten con el perfil. */
.native-post-head {
  min-height: 72px;
  gap: 14px;
}

.native-post-head-side {
  min-width: 132px;
  max-width: 180px;
}

.native-post-head-side .query-drawer-post-date {
  max-width: none;
  white-space: nowrap;
  font-size: 10px;
}

.native-post-meta {
  row-gap: 4px;
}

/* Los fixes runtime anteriores limitaban media a 190px con !important.
   Estas reglas restituyen una geometría útil para tarjetas nativas. */
.native-post-card .query-drawer-media-image,
.native-post-card .query-drawer-media-video {
  max-height: none !important;
  object-fit: contain !important;
}

/* EN VIVO: media grande y lectura cómoda. */
#queryDrawerPosts .native-post-card .query-drawer-media-slide {
  height: clamp(380px, 48vw, 680px) !important;
  min-height: 320px !important;
  max-height: 680px !important;
}

#queryDrawerPosts .platform-instagram .query-drawer-media-slide {
  height: min(70vh, 680px) !important;
  max-height: 680px !important;
}

#queryDrawerPosts .platform-facebook.type-video .query-drawer-media-slide,
#queryDrawerPosts .platform-facebook.type-reel .query-drawer-media-slide {
  height: min(68vh, 660px) !important;
  max-height: 660px !important;
}

#queryDrawerPosts .platform-tiktok .query-drawer-media-slide {
  height: min(74vh, 720px) !important;
  max-height: 720px !important;
}

/* ¿QUÉ? > Publicaciones: media algo más compacta para dos columnas. */
.drawer-native-feed-grid .native-post-card .query-drawer-media-slide {
  height: clamp(280px, 34vw, 480px) !important;
  min-height: 260px !important;
  max-height: 480px !important;
}

.drawer-native-feed-grid .platform-instagram .query-drawer-media-slide {
  height: min(58vh, 520px) !important;
  max-height: 520px !important;
}

.drawer-native-feed-grid .platform-facebook.type-video .query-drawer-media-slide,
.drawer-native-feed-grid .platform-facebook.type-reel .query-drawer-media-slide {
  height: min(58vh, 520px) !important;
  max-height: 520px !important;
}

.drawer-native-feed-grid .platform-tiktok .query-drawer-media-slide {
  height: min(66vh, 600px) !important;
  max-height: 600px !important;
}

/* Texto: En vivo permite más contexto; ¿Qué? conserva densidad visual. */
#queryDrawerPosts .native-post-copy {
  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 8 !important;
  overflow: hidden !important;
}

.drawer-native-feed-grid .native-post-copy {
  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 5 !important;
  overflow: hidden !important;
}

.platform-web .query-drawer-post-copy {
  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 5 !important;
  overflow: hidden !important;
}

/* Más aire en tarjetas al disponer de mayor ancho. */
