appsmith.onReady(function () {
  var currentPage = 1;
  var currentQueryView = 'constructor';
  var currentMode = 'home';
  var currentStep = 0;
  var groups = [];
  var selectedTargetIds = [];
  var useWeb = false;
  var queryPeriod = '7d';
  var queryDateFrom = '';
  var queryDateTo = '';
  var lastQueriesValue = null;
  var lastTargetsValue = null;
  var lastModeValue = null;
  var lastStepValue = null;
  var lastGroupsValue = null;
  var lastTargetIdsValue = null;
  var lastUseWebValue = null;
  var lastAiResponseValue = null;
  var lastSelectedQueryIdValue = null;
  var aiRequestPending = false;
  var aiFeedbackMessage = '';
  var aiWarnings = [];
  var aiGenerateArmed = false;
  var aiGenerateInstruction = '';
  var aiDraftInstruction = null;
  var sourceSearchTimer = null;
  var lastSourceManagementValue = null;
  var pendingSaveConfirmation = null;
  var sourceUiState = {
    page: 1,
    pageSize: 25,
    search: '',
    platformFilter: '',
    statusFilter: '',
    formPlatform: '',
    formHandle: '',
    formExternalId: '',
    actionId: ''
  };
  var sourceUiStateInitialized = false;
  var drawerState = {
    open: false,
    activeSection: 'live',
    range: '12h',
    customStart: null,
    customEnd: null,
    feedSort: 'recent',
    whatTab: 'publications'
  };
  var lastDrawerPostsValue = null;
  var lastDrawerActorsValue = null;
  var drawerPostsCacheByQuery = {};
  var drawerActorsCacheByQuery = {};
  var drawerSelection = {
    id: '',
    name: '',
    query: null
  };
  var lastNonEmptyDrawerPosts = [];
  var lastNonEmptyDrawerActors = [];
  function getModel() {
    return appsmith.model || {};
  }
  function escapeHtml(value) {
    var div = document.createElement('div');
    div.textContent = value == null ? '' : String(value);
    return div.innerHTML;
  }
  function asArray(value) {
    if (Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return Array.isArray(parsed) ? parsed : [];
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return Array.isArray(decodedParsed) ? decodedParsed : [];
      } catch (decodedError) {
        return [];
      }
    }
  }
  function asObject(value) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return {};
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return decodedParsed && typeof decodedParsed === 'object' && !Array.isArray(decodedParsed) ? decodedParsed : {};
      } catch (decodedError) {
        return {};
      }
    }
  }
  function normalizeTerms(value) {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map(function (term) {
      return String(term == null ? '' : term).trim();
    }).filter(function (term) {
      return term !== '';
    });
  }
  function createEmptyGroup(groupNo) {
    return {
      group_no: groupNo,
      include: [],
      and: [],
      and_not: []
    };
  }
  function normalizeGroup(group, index) {
    return {
      group_no: index + 1,
      include: normalizeTerms(group && group.include),
      and: normalizeTerms(group && group.and),
      and_not: normalizeTerms(group && group.and_not)
    };
  }
  function loadGroupsFromModel() {
    var raw = getModel().query_groups_json;
    var parsed = [];
    if (Array.isArray(raw)) {
      parsed = raw;
    } else if (typeof raw === 'string' && raw.trim() !== '') {
      try {
        parsed = JSON.parse(raw);
      } catch (error) {
        parsed = [];
      }
    }
    if (!Array.isArray(parsed) || parsed.length === 0) {
      groups = [createEmptyGroup(1)];
      return;
    }
    groups = parsed.map(normalizeGroup);
  }
  function loadSourcesFromModel() {
    selectedTargetIds = asArray(getModel().query_target_ids_json).map(function (id) {
      return String(id);
    });
    useWeb = getModel().query_use_web === true || String(getModel().query_use_web).toLowerCase() === 'true';
  }
  function getMexicoTodayYmd() {
    var parts = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(new Date());
    var values = {};
    parts.forEach(function (part) {
      values[part.type] = part.value;
    });
    return values.year + '-' + values.month + '-' + values.day;
  }
  function shiftYmd(value, days) {
    var match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) {
      return '';
    }
    var date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
    date.setUTCDate(date.getUTCDate() + Number(days || 0));
    return date.toISOString().slice(0, 10);
  }
  function normalizeQueryPeriod(value) {
    var normalized = String(value || '').trim().toLowerCase();
    return normalized === 'today' || normalized === '7d' || normalized === '30d' || normalized === 'custom' ? normalized : '7d';
  }
  function applyPresetPeriod(period) {
    var normalized = normalizeQueryPeriod(period);
    var today = getMexicoTodayYmd();
    queryPeriod = normalized;
    if (normalized === 'today') {
      queryDateFrom = today;
      queryDateTo = today;
      return;
    }
    if (normalized === '30d') {
      queryDateFrom = shiftYmd(today, -29);
      queryDateTo = today;
      return;
    }
    if (normalized === 'custom') {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(queryDateFrom)) {
        queryDateFrom = shiftYmd(today, -6);
      }
      if (!/^\d{4}-\d{2}-\d{2}$/.test(queryDateTo)) {
        queryDateTo = today;
      }
      return;
    }
    queryDateFrom = shiftYmd(today, -6);
    queryDateTo = today;
  }
  function loadPeriodFromModel() {
    var model = getModel();
    var period = normalizeQueryPeriod(model.query_period || '7d');
    var dateFrom = String(model.query_date_from || '').trim();
    var dateTo = String(model.query_date_to || '').trim();
    queryPeriod = period;
    if (period === 'custom' && /^\d{4}-\d{2}-\d{2}$/.test(dateFrom) && /^\d{4}-\d{2}-\d{2}$/.test(dateTo)) {
      queryDateFrom = dateFrom;
      queryDateTo = dateTo;
      return;
    }
    applyPresetPeriod(period);
  }
  function hasValidWebPeriod() {
    if (!useWeb) {
      return true;
    }
    var today = getMexicoTodayYmd();
    return /^\d{4}-\d{2}-\d{2}$/.test(queryDateFrom) && /^\d{4}-\d{2}-\d{2}$/.test(queryDateTo) && queryDateFrom <= queryDateTo && queryDateTo <= today;
  }
  function formatYmd(value) {
    var match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) {
      return '';
    }
    return match[3] + '/' + match[2] + '/' + match[1];
  }
  function getQueryPeriodLabel() {
    if (queryPeriod === 'today') {
      return 'Hoy';
    }
    if (queryPeriod === '30d') {
      return 'Últimos 30 días';
    }
    if (queryPeriod === 'custom') {
      return 'Personalizado';
    }
    return 'Últimos 7 días';
  }
  function getQueryPeriodSummary() {
    if (!useWeb) {
      return 'No aplica';
    }
    if (!hasValidWebPeriod()) {
      return 'Rango inválido';
    }
    return getQueryPeriodLabel() + ' · ' + formatYmd(queryDateFrom) + ' – ' + formatYmd(queryDateTo);
  }
  async function syncPeriodPayload() {
    try {
      await appsmith.updateModel({
        query_period: queryPeriod,
        query_date_from: queryDateFrom,
        query_date_to: queryDateTo
      });
    } catch (error) {
      console.error('No fue posible sincronizar el periodo de búsqueda:', error);
    }
  }
  async function setQueryPeriod(period) {
    applyPresetPeriod(period);
    await syncPeriodPayload();
    renderCurrentView();
  }
  async function setCustomPeriodDate(field, value) {
    var normalized = String(value || '').trim();
    queryPeriod = 'custom';
    if (field === 'from') {
      queryDateFrom = normalized;
    } else if (field === 'to') {
      queryDateTo = normalized;
    }
    await syncPeriodPayload();
    renderCurrentView();
  }
  function renderQueryPeriodSelector() {
    var today = getMexicoTodayYmd();
    var invalid = useWeb && !hasValidWebPeriod();
    return '<div class="query-period-section">' + '<div class="manual-sources-heading">' + '<div>' + '<span>' + 'Periodo de búsqueda' + '</span>' + '<strong>' + 'Ventana temporal' + '</strong>' + '</div>' + '<small>' + (useWeb ? escapeHtml(getQueryPeriodSummary()) : 'Se aplicará cuando Web esté activa') + '</small>' + '</div>' + '<div class="query-period-options">' + '<button type="button" class="query-period-option' + (queryPeriod === 'today' ? ' active' : '') + '" data-query-period="today">' + '<strong>Hoy</strong>' + '<span>Día calendario actual</span>' + '</button>' + '<button type="button" class="query-period-option' + (queryPeriod === '7d' ? ' active' : '') + '" data-query-period="7d">' + '<strong>Últimos 7 días</strong>' + '<span>Incluye hoy</span>' + '</button>' + '<button type="button" class="query-period-option' + (queryPeriod === '30d' ? ' active' : '') + '" data-query-period="30d">' + '<strong>Últimos 30 días</strong>' + '<span>Incluye hoy</span>' + '</button>' + '<button type="button" class="query-period-option' + (queryPeriod === 'custom' ? ' active' : '') + '" data-query-period="custom">' + '<strong>Personalizado</strong>' + '<span>Selecciona fechas</span>' + '</button>' + '</div>' + (queryPeriod === 'custom' ? '<div class="query-period-custom">' + '<label>' + '<span>Desde</span>' + '<input id="queryPeriodFrom" type="date" max="' + escapeHtml(today) + '" value="' + escapeHtml(queryDateFrom) + '">' + '</label>' + '<label>' + '<span>Hasta</span>' + '<input id="queryPeriodTo" type="date" max="' + escapeHtml(today) + '" value="' + escapeHtml(queryDateTo) + '">' + '</label>' + '</div>' : '') + (invalid ? '<div class="query-period-error">' + 'Selecciona un rango válido. La fecha inicial no puede ser posterior a la final y no se permiten fechas futuras.' + '</div>' : '') + '</div>';
  }
