.query-drawer-empty > span:not(.query-drawer-empty-icon) {
  max-width: 360px;

  color: var(--muted-soft);

  font-size: 8.5px;
  line-height: 1.5;
}

.query-drawer-placeholder {
  min-height: 420px;

  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;

  padding: 42px;

  border:
    1px solid rgba(167, 205, 222, 0.46);

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.98),
      rgba(247, 250, 252, 0.94)
