  max-width: 520px;

  margin-top: 7px;

  color: var(--muted);

  font-size: 9.5px;
  line-height: 1.65;
}


/* RESPONSIVE */

@media (max-width: 1180px) {
  .query-drawer {
    width: 88%;
  }

  .query-drawer-live-grid {
    grid-template-columns:
      minmax(0, 1fr)
      minmax(260px, 0.68fr);
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      1fr;
  }
}


@media (max-width: 920px) {
  .query-drawer {
    width: 94%;
  }

  .query-drawer-live-grid {
    grid-template-columns:
      1fr;
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .query-drawer-commandbar {
    align-items: flex-start;
    flex-direction: column;
  }
}


@media (max-width: 700px) {
  .query-drawer {
    width: 100%;
