  .query-drawer-command-note {
    display: none;
  }

  .query-drawer-tabs {
    padding-left: 10px;
    padding-right: 10px;
  }

  .query-drawer-content {
    padding:
      10px;
  }

  .query-drawer-posts {
    grid-template-columns:
      1fr;
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .query-drawer-placeholder {
    min-height: 330px;

    padding:
      26px 18px;
  }
}


@media (max-width: 460px) {
  .query-drawer-query-mark {
    display: none;
