/* =========================================================
   PERIODO DE BÚSQUEDA WEB
   ========================================================= */

.query-period-section {
  margin-top: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
}

.query-period-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.query-period-option {
  min-height: 74px;
  padding: 12px 13px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface);
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    box-shadow 0.16s ease,
    transform 0.16s ease;
}

.query-period-option:hover {
  border-color: var(--light-blue);
  background: var(--paper);
  transform: translateY(-1px);
}

.query-period-option.active {
  border-color: var(--blue);
  background: rgba(46, 155, 203, 0.08);
  box-shadow:
    0 0 0 2px
    rgba(41, 114, 169, 0.08);
}

.query-period-option strong {
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

.query-period-option span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.query-period-custom {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.query-period-custom label {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.query-period-custom label > span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.query-period-custom input {
  width: 100%;
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
  color: var(--ink);
  outline: none;
}

.query-period-custom input:focus {
  border-color: var(--blue);
  box-shadow:
    0 0 0 3px
    rgba(41, 114, 169, 0.08);
}

.query-period-error {
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(169, 92, 92, 0.26);
  border-radius: 11px;
  background: rgba(169, 92, 92, 0.06);
  color: var(--danger);
  font-size: 10px;
  line-height: 1.45;
}

.query-period-preview {
  margin-top: 12px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.query-period-preview > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.query-period-preview span {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
}

.query-period-preview strong {
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

.query-period-preview small {
  color: var(--muted);
  font-size: 10px;
  text-align: right;
}

@media (max-width: 900px) {
  .query-period-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .query-period-options,
  .query-period-custom {
    grid-template-columns: 1fr;
  }

  .query-period-preview {
    align-items: flex-start;
    flex-direction: column;
  }

  .query-period-preview small {
    text-align: left;
  }
}

/* =========================================================
   DRAWER — TARJETAS NATIVAS POR PLATAFORMA
   ========================================================= */

.query-drawer-posts {
  grid-template-columns: 1fr;
  gap: 16px;
  padding: 14px;
}

.drawer-native-feed-grid {
