/* =========================================================
   ¿DÓNDE? — COBERTURA GEOGRÁFICA WEB
   ÚNICO CAMBIO V6
   ========================================================= */

.drawer-geo-methodology {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 11px;
  align-items: start;
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(46, 155, 203, 0.20);
  border-radius: 13px;
  background: linear-gradient(135deg, rgba(46, 155, 203, 0.055), rgba(167, 205, 222, 0.10));
}

.drawer-geo-methodology-icon {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(46, 155, 203, 0.12);
  color: var(--blue);
  font-size: 13px;
  font-weight: 900;
}

.drawer-geo-methodology p {
  margin: 0;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.55;
}

.drawer-geo-methodology strong {
  color: var(--ink);
}

.drawer-geo-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(310px, 0.82fr);
  gap: 12px;
  align-items: stretch;
}

.drawer-geo-map-card {
  min-width: 0;
  overflow: hidden;
}

.drawer-geo-map {
  position: relative;
  min-height: 430px;
  overflow: hidden;
  border-radius: 0 0 13px 13px;
  background:
    radial-gradient(circle at 22% 76%, rgba(255,255,255,0.92), rgba(255,255,255,0) 30%),
    linear-gradient(180deg, #dff2fb 0%, #bfe3f3 100%);
}

.drawer-geo-map::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.38;
  background-image:
    linear-gradient(rgba(255,255,255,0.62) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.62) 1px, transparent 1px);
  background-size: 58px 58px;
  pointer-events: none;
}

.drawer-geo-map-shape {
  position: absolute;
  inset: 8% 4% 7% 4%;
  width: 92%;
  height: 85%;
  filter: drop-shadow(0 10px 18px rgba(28, 81, 108, 0.10));
}

.drawer-geo-mexico-baja,
.drawer-geo-mexico-main,
.drawer-geo-mexico-yucatan {
  fill: url(#drawerMexicoFill);
  stroke: rgba(91, 128, 146, 0.60);
  stroke-width: 2;
}

.drawer-geo-map-label {
  position: absolute;
  z-index: 2;
  color: rgba(42, 89, 120, 0.55);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  pointer-events: none;
}

.drawer-geo-map-label.north { left: 49%; top: 8%; }
.drawer-geo-map-label.gulf { left: 63%; top: 40%; }
.drawer-geo-map-label.pacific { left: 13%; bottom: 18%; }

.drawer-geo-marker {
  position: absolute;
  z-index: 4;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 3px solid rgba(255,255,255,0.94);
  border-radius: 50%;
  background: linear-gradient(145deg, #2E9BCB, #1267B4);
  box-shadow: 0 5px 14px rgba(13, 93, 155, 0.27);
  color: #FFFFFF;
}

.drawer-geo-marker strong {
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
}

.drawer-geo-marker > span {
  position: absolute;
  top: calc(100% + 3px);
  left: 50%;
  transform: translateX(-50%);
  max-width: 92px;
  overflow: hidden;
  color: #26485d;
  font-size: 8.5px;
  font-weight: 800;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-shadow: 0 1px 0 rgba(255,255,255,0.9);
}

.drawer-geo-map-legend {
  position: absolute;
  z-index: 5;
  left: 13px;
  bottom: 13px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px 10px;
  max-width: 260px;
  padding: 9px 11px;
  border: 1px solid rgba(255,255,255,0.80);
  border-radius: 11px;
  background: rgba(255,255,255,0.90);
  backdrop-filter: blur(8px);
  box-shadow: 0 7px 18px rgba(47, 50, 59, 0.06);
}

.drawer-geo-map-legend strong {
  width: 100%;
  color: var(--ink);
  font-size: 9.5px;
}

.drawer-geo-map-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 8.5px;
}

.drawer-geo-map-legend i {
  display: inline-block;
  border-radius: 50%;
  background: linear-gradient(145deg, #2E9BCB, #1267B4);
}

.drawer-geo-map-legend i.small { width: 9px; height: 9px; }
.drawer-geo-map-legend i.large { width: 17px; height: 17px; }

.drawer-geo-map-caption {
  position: absolute;
  z-index: 5;
  right: 12px;
  bottom: 12px;
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(255,255,255,0.84);
  color: var(--muted-soft);
  font-size: 8.5px;
  font-weight: 700;
}

.drawer-geo-side {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.drawer-geo-ranking {
  max-height: 248px;
  overflow-y: auto;
  padding: 4px 10px 10px;
  scrollbar-gutter: stable;
}

.drawer-geo-rank-row {
  display: grid;
  grid-template-columns: 26px 18px minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
  min-height: 39px;
  padding: 5px 8px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.22);
}

.drawer-geo-rank-row.active {
  border-left: 3px solid var(--cyan);
  border-radius: 7px;
  background: rgba(46, 155, 203, 0.06);
}

.drawer-geo-rank-index {
  color: var(--muted-soft);
  font-size: 10px;
  font-weight: 800;
}

.drawer-geo-pin {
  color: var(--cyan);
  font-size: 10px;
}

.drawer-geo-rank-row > strong {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.drawer-geo-rank-value {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  color: var(--blue);
  font-size: 12px;
  font-weight: 900;
}

.drawer-geo-rank-value small {
  color: var(--muted-soft);
  font-size: 7.5px;
  font-weight: 650;
}

.drawer-geo-selected-card {
  overflow: hidden;
}

.drawer-geo-selected-head {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 9px;
  align-items: center;
  padding: 12px;
}

.drawer-geo-selected-pin {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(46, 155, 203, 0.12);
  color: var(--blue);
  font-size: 11px;
}

.drawer-geo-selected-head > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.drawer-geo-selected-head small {
  color: var(--muted-soft);
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.drawer-geo-selected-head strong {
  color: var(--ink);
  font-size: 15px;
  font-weight: 850;
}

.drawer-geo-selected-count {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  color: var(--blue);
  font-size: 17px;
  font-weight: 900;
}

.drawer-geo-selected-count small {
  margin-top: 2px;
  color: var(--muted-soft);
  font-size: 7.5px;
  font-weight: 650;
  text-transform: none;
}

.drawer-geo-selected-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  padding: 0 12px 11px;
}

.drawer-geo-selected-meta span {
  padding: 8px 9px;
  border-radius: 8px;
  background: rgba(167, 205, 222, 0.09);
  color: var(--muted);
  font-size: 8.5px;
}

.drawer-geo-selected-meta strong {
  margin-right: 4px;
  color: var(--ink);
  font-size: 11px;
}

.drawer-analysis-card-head.compact {
  padding-top: 9px;
  padding-bottom: 7px;
}

.drawer-geo-source-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 12px 12px;
}

.drawer-geo-source-chips span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 27px;
  padding: 0 8px;
  border: 1px solid rgba(167, 205, 222, 0.46);
  border-radius: 999px;
  background: #FFFFFF;
  color: var(--muted);
  font-size: 8.5px;
}

.drawer-geo-source-chips strong {
  color: var(--blue);
  font-size: 9px;
}

.drawer-geo-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.drawer-geo-kpi-grid article {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 13px;
  border: 1px solid rgba(167, 205, 222, 0.52);
  border-radius: 12px;
  background: #FFFFFF;
}

.drawer-geo-kpi-icon {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 34px;
  border-radius: 9px;
  background: rgba(46, 155, 203, 0.09);
  color: var(--blue);
  font-size: 12px;
  font-weight: 900;
}

.drawer-geo-kpi-grid article > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.drawer-geo-kpi-grid article strong {
  color: var(--ink);
  font-size: 21px;
  line-height: 1;
  font-weight: 900;
}

.drawer-geo-kpi-grid article span:not(.drawer-geo-kpi-icon) {
  margin-top: 3px;
  color: var(--ink-soft);
  font-size: 9.5px;
  font-weight: 750;
}

.drawer-geo-kpi-grid article small {
  margin-top: 2px;
  color: var(--muted-soft);
  font-size: 8px;
}

.drawer-geo-support-grid {
  margin-top: 12px;
}

.drawer-geo-sources-card {
  margin-top: 12px;
}

.drawer-analysis-empty.compact {
  min-height: 120px;
  padding: 18px;
}

@media (max-width: 1180px) {
  .drawer-geo-main-grid {
    grid-template-columns: 1fr;
  }

  .drawer-geo-side {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .drawer-geo-map {
    min-height: 360px;
  }

  .drawer-geo-side,
  .drawer-geo-kpi-grid {
    grid-template-columns: 1fr;
  }

  .drawer-geo-map-caption {
    display: none;
  }
}

@media (max-width: 520px) {
  .drawer-geo-map {
    min-height: 300px;
  }

  .drawer-geo-marker > span,
  .drawer-geo-map-label {
    display: none;
  }

  .drawer-geo-selected-meta {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   ¿DÓNDE? — MAPA GEOGRÁFICO REAL INEGI
   ÚNICO CAMBIO V7
   ========================================================= */

.drawer-geo-map {
  min-height: 430px;
  background: #d9eff8;
}

.drawer-geo-map::before {
  display: none;
}

.drawer-geo-map-loading,
.drawer-geo-map-error,
.drawer-geo-map-no-data {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  padding: 24px;
  text-align: center;
}

.drawer-geo-map-loading > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.drawer-geo-map-loading strong,
.drawer-geo-map-error strong,
.drawer-geo-map-no-data strong {
  color: var(--ink);
  font-size: 12px;
  font-weight: 850;
}

.drawer-geo-map-loading small,
.drawer-geo-map-error span,
.drawer-geo-map-no-data span {
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.5;
}

.drawer-geo-map-spinner {
  width: 24px;
  height: 24px;
  border: 3px solid rgba(41, 114, 169, 0.15);
  border-top-color: var(--blue);
  border-radius: 50%;
  animation: drawerGeoSpin 0.85s linear infinite;
}

@keyframes drawerGeoSpin {
  to { transform: rotate(360deg); }
}

.drawer-geo-map-svg-real {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.drawer-geo-ocean {
  fill: #d9eff8;
}

.drawer-geo-state {
  fill: #f7fafc;
  stroke: rgba(74, 112, 132, 0.76);
  stroke-width: 1.15;
  vector-effect: non-scaling-stroke;
  transition: fill 0.16s ease, stroke 0.16s ease;
}

.drawer-geo-state.detected {
  fill: #d7edf7;
  stroke: rgba(31, 111, 161, 0.92);
  stroke-width: 1.35;
}

.drawer-geo-state-group:hover .drawer-geo-state {
  fill: #edf6fa;
}

.drawer-geo-state-group.detected:hover .drawer-geo-state {
  fill: #c5e5f3;
}

.drawer-geo-svg-marker {
  pointer-events: none;
  filter: drop-shadow(0 4px 6px rgba(13, 93, 155, 0.22));
}

.drawer-geo-svg-marker circle {
  fill: #1d86c4;
  stroke: rgba(255, 255, 255, 0.98);
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

.drawer-geo-svg-count {
  fill: #FFFFFF;
  font-weight: 900;
  font-family: inherit;
}

.drawer-geo-svg-label {
  fill: #203b4b;
  font-size: 8.5px;
  font-weight: 850;
  paint-order: stroke;
  stroke: rgba(255,255,255,0.94);
  stroke-width: 3px;
  stroke-linejoin: round;
}

.drawer-geo-map-caption {
  max-width: 260px;
  text-align: right;
}

.drawer-geo-map-error {
  background: #F8FBFC;
}

@media (max-width: 760px) {
  .drawer-geo-map-svg-real {
    min-width: 720px;
    width: 720px;
    left: 50%;
    transform: translateX(-50%);
  }

  .drawer-geo-svg-label {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .drawer-geo-map-spinner {
    animation: none;
  }
}

