                today,
                -6
            );

        queryDateTo =
            today;
    }

    function loadPeriodFromModel() {
        var model =
            getModel();

        var period =
            normalizeQueryPeriod(
                model.query_period ||
                '7d'
            );

        var dateFrom =
            String(
                model.query_date_from ||
                ''
            ).trim();

        var dateTo =
            String(
                model.query_date_to ||
                ''
            ).trim();

        queryPeriod =
            period;

        if (
            period ===
                'custom' &&
            /^\d{4}-\d{2}-\d{2}$/.test(
                dateFrom
            ) &&
            /^\d{4}-\d{2}-\d{2}$/.test(
                dateTo
            )
        ) {
            queryDateFrom =
                dateFrom;

            queryDateTo =
                dateTo;

            return;
        }

        applyPresetPeriod(
            period
        );
    }

    function hasValidWebPeriod() {
        if (!useWeb) {
            return true;
        }

        var today =
            getMexicoTodayYmd();

        return (
            /^\d{4}-\d{2}-\d{2}$/.test(
                queryDateFrom
            ) &&
            /^\d{4}-\d{2}-\d{2}$/.test(
                queryDateTo
            ) &&
            queryDateFrom <=
                queryDateTo &&
            queryDateTo <=
                today
        );
    }

    function formatYmd(value) {
        var match =
            String(
                value || ''
            )
            .match(
                /^(\d{4})-(\d{2})-(\d{2})$/
            );

        if (!match) {
            return '';
        }

        return (
            match[3] +
            '/' +
            match[2] +
            '/' +
            match[1]
        );
    }

    function getQueryPeriodLabel() {
        if (
            queryPeriod ===
            'today'
        ) {
            return 'Hoy';
        }

        if (
            queryPeriod ===
            '30d'
        ) {
            return 'Últimos 30 días';
        }

        if (
            queryPeriod ===
            'custom'
        ) {
            return 'Personalizado';
        }

        return 'Últimos 7 días';
    }

    function getQueryPeriodSummary() {
        if (!useWeb) {
            return 'No aplica';
        }

        if (!hasValidWebPeriod()) {
            return 'Rango inválido';
        }

        return (
            getQueryPeriodLabel() +
            ' · ' +
            formatYmd(
                queryDateFrom
            ) +
            ' – ' +
            formatYmd(
                queryDateTo
            )
        );
    }

    async function syncPeriodPayload() {
        try {
            await appsmith.updateModel({
                query_period:
                    queryPeriod,

                query_date_from:
                    queryDateFrom,

                query_date_to:
                    queryDateTo
            });
        } catch (error) {
