    function formatDate(value) {
        if (!value) {
            return '';
        }
        try {
            return new Intl.DateTimeFormat('es', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric'
            }).format(new Date(value));
        } catch (error) {
            return '';
        }
    }

