    function initializeSourceUiState(model) {
        if (sourceUiStateInitialized) {
            return;
        }
        var sourceModel = model || getModel();
        var page = parseInt(sourceModel.sourcePage || 1, 10);
        var pageSize = parseInt(sourceModel.sourcePageSize || 25, 10);
        sourceUiState.page = !isNaN(page) && page > 0 ? page : 1;
        sourceUiState.pageSize = !isNaN(pageSize) && pageSize > 0 ? Math.min(pageSize, 100) : 25;
        sourceUiState.search = String(sourceModel.sourceSearch || '').trim();
        sourceUiState.platformFilter = String(sourceModel.sourcePlatformFilter || '').trim();
        sourceUiState.statusFilter = String(sourceModel.sourceStatusFilter || '').trim();
        sourceUiState.formPlatform = String(sourceModel.sourceFormPlatform || '').trim();
        sourceUiState.formHandle = String(sourceModel.sourceFormHandle || '').trim();
        sourceUiState.formExternalId = String(sourceModel.sourceFormExternalId || '').trim();
        sourceUiState.actionId = String(sourceModel.sourceActionId || '').trim();
        sourceUiStateInitialized = true;
    }

    function applySourceUiStatePatch(patch) {
        initializeSourceUiState();
        patch = patch || {};
        if (Object.prototype.hasOwnProperty.call(patch, 'sourcePage')) {
            var page = parseInt(patch.sourcePage, 10);
            sourceUiState.page = !isNaN(page) && page > 0 ? page : 1;
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourcePageSize')) {
            var pageSize = parseInt(patch.sourcePageSize, 10);
            sourceUiState.pageSize = !isNaN(pageSize) && pageSize > 0 ? Math.min(pageSize, 100) : 25;
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceSearch')) {
            sourceUiState.search = String(patch.sourceSearch || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourcePlatformFilter')) {
            sourceUiState.platformFilter = String(patch.sourcePlatformFilter || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceStatusFilter')) {
            sourceUiState.statusFilter = String(patch.sourceStatusFilter || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceFormPlatform')) {
            sourceUiState.formPlatform = String(patch.sourceFormPlatform || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceFormHandle')) {
            sourceUiState.formHandle = String(patch.sourceFormHandle || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceFormExternalId')) {
            sourceUiState.formExternalId = String(patch.sourceFormExternalId || '').trim();
        }
        if (Object.prototype.hasOwnProperty.call(patch, 'sourceActionId')) {
            sourceUiState.actionId = String(patch.sourceActionId || '').trim();
        }
    }

    function getSourceModelPatch() {
        initializeSourceUiState();
        return {
            sourcePage: sourceUiState.page,
            sourcePageSize: sourceUiState.pageSize,
            sourceSearch: sourceUiState.search,
            sourcePlatformFilter: sourceUiState.platformFilter,
            sourceStatusFilter: sourceUiState.statusFilter,
            sourceFormPlatform: sourceUiState.formPlatform,
            sourceFormHandle: sourceUiState.formHandle,
            sourceFormExternalId: sourceUiState.formExternalId,
            sourceActionId: sourceUiState.actionId
        };
    }

    function getSourcePage() {
        initializeSourceUiState();
        return sourceUiState.page;
    }

    function getSourcePageSize() {
        initializeSourceUiState();
        return sourceUiState.pageSize;
    }

    function getSourceTotalCount() {
        var value = Number(getModel().sourceTotalCount || 0);
        if (!isFinite(value) || value < 0) {
            return 0;
        }
        return value;
    }

    function getSourceTotalPages() {
        var total = getSourceTotalCount();
        var pageSize = getSourcePageSize();
        return Math.max(1, Math.ceil(total / pageSize));
    }

    function getSourceManagementSignature(model) {
        var sourceModel = model || getModel();
        return [
            String(sourceModel.sources || ''),
            String(sourceModel.sourcePlatforms || ''),
            String(sourceModel.sourceTotalCount || 0),
            String(sourceModel.sourcePage || 1),
            String(sourceModel.sourcePageSize || 25),
            String(sourceModel.sourceSearch || ''),
            String(sourceModel.sourcePlatformFilter || ''),
            String(sourceModel.sourceStatusFilter || ''),
            String(sourceModel.sourceFormPlatform || ''),
            String(sourceModel.sourceFormHandle || ''),
            String(sourceModel.sourceFormExternalId || ''),
            String(sourceModel.sourceActionId || '')
        ].join('\u001f');
    }

    function getSourcePlatformName(code) {
        var normalizedCode = String(code || '').trim();
        var platform = getSourcePlatforms().find(function(item) {
            return (item && String(item.code || '') === normalizedCode);
        });
        if (platform && platform.display_name) {
            return String(platform.display_name);
        }
        return formatPlatformLabel(normalizedCode);
    }

    function getSourcePlatformInitial(value) {
        var text = String(value || '').trim();
        if (!text) {
            return '?';
        }
        return text.charAt(0).toUpperCase();
    }

    function renderSourcePlatformSelectors(sourceModel) {
        sourceModel = sourceModel || getModel();
        var platforms = asArray(sourceModel.sourcePlatforms);
        var formSelect = document.getElementById('sourcePlatform');
        var filterSelect = document.getElementById('sourcesPlatformFilter');
        initializeSourceUiState(sourceModel);
        var formValue = sourceUiState.formPlatform;
        var filterValue = sourceUiState.platformFilter;

        function buildGroupedOptions(items) {
            var grouped = {};
            items.forEach(function(platform) {
                var category = String(platform.category || 'Otras').trim() || 'Otras';
                if (!grouped[category]) {
                    grouped[category] = [];
                }
                grouped[category].push(platform);
            });
            return Object.keys(grouped).sort(function(a, b) {
                return a.localeCompare(b, 'es', {
                    sensitivity: 'base'
                });
            }).map(function(category) {
                var options = grouped[category].slice().sort(function(a, b) {
                    return String(a.display_name || a.code || '').localeCompare(String(b.display_name || b.code || ''), 'es', {
                        sensitivity: 'base'
                    });
                }).map(function(platform) {
                    return ('<option value="' + escapeHtml(platform.code) + '">' + escapeHtml(platform.display_name || platform.code) + '</option>');
                }).join('');
                return ('<optgroup label="' + escapeHtml(category) + '">' + options + '</optgroup>');
            }).join('');
        }
        if (formSelect) {
            var eligiblePlatforms = platforms.filter(function(platform) {
                return (platform && platform.code && toBoolean(platform.is_active));
            });
            formSelect.innerHTML = '<option value="">' + 'Selecciona plataforma' + '</option>' + buildGroupedOptions(eligiblePlatforms);
            if (eligiblePlatforms.some(function(platform) {
                    return (String(platform.code) === formValue);
                })) {
                formSelect.value = formValue;
            } else if (document.activeElement !== formSelect) {
                formSelect.value = '';
            }
        }
        if (filterSelect) {
            var filterPlatforms = platforms.filter(function(platform) {
                return (platform && platform.code);
            });
            filterSelect.innerHTML = '<option value="">' + 'Todas las plataformas' + '</option>' + buildGroupedOptions(filterPlatforms);
            filterSelect.value = filterValue;
        }
    }

    function renderSourceRow(source) {
        var id = String(source && source.id || '').trim();
        var platformCode = String(source && source.platform || '').trim();
        var platformName = String(source && source.platform_name || getSourcePlatformName(platformCode));
        var status = String(source && source.status || '').trim().toLowerCase();
        var statusClass = status === 'active' ? 'active' : 'inactive';
        var statusLabel = status === 'active' ? 'Activa' : status === 'inactive' ? 'Inactiva' : status || 'Sin estado';
        return ('<tr>' + '<td>' + '<span class="sources-platform">' + '<span class="sources-platform-icon">' + escapeHtml(getSourcePlatformInitial(platformName)) + '</span>' + '<span>' + escapeHtml(platformName) + '</span>' + '</span>' + '</td>' + '<td>' + '<span class="sources-handle">' + escapeHtml(source && source.handle || '') + '</span>' + '</td>' + '<td>' + '<span class="sources-external-id">' + escapeHtml(source && source.external_profile_id || '') + '</span>' + '</td>' + '<td>' + '<span class="sources-status ' + escapeHtml(statusClass) + '">' + escapeHtml(statusLabel) + '</span>' + '</td>' + '<td>' + '<span class="sources-created">' + escapeHtml(source && (source.created_fmt || formatDate(source.created_at)) || '') + '</span>' + '</td>' + '<td>' + '<div class="sources-actions">' + '<button' + ' type="button"' + ' class="sources-action-button"' + ' data-source-toggle-id="' + escapeHtml(id) + '">' + (status === 'active' ? 'Desactivar' : 'Activar') + '</button>' + '<button' + ' type="button"' + ' class="sources-action-button danger"' + ' data-source-delete-id="' + escapeHtml(id) + '">' + 'Eliminar' + '</button>' + '</div>' + '</td>' + '</tr>');
    }

    function renderSourcesManagement(sourceModel) {
        sourceModel = sourceModel || getModel();
        var sources = asArray(sourceModel.sources);
        var totalCount = Number(sourceModel.sourceTotalCount || 0);
        if (!isFinite(totalCount) || totalCount < 0) {
            totalCount = 0;
        }
        initializeSourceUiState(sourceModel);
        var page = sourceUiState.page;
        var pageSize = sourceUiState.pageSize;
        var totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
        var countElement = document.getElementById('sourcesCount');
        var searchInput = document.getElementById('sourcesSearch');
        var statusFilter = document.getElementById('sourcesStatusFilter');
        var handleInput = document.getElementById('sourceHandle');
        var externalIdInput = document.getElementById('sourceExternalId');
        var tableBody = document.getElementById('sourcesTable');
        var pagination = document.getElementById('sourcesPagination');
        var previousButton = document.getElementById('sourcesPrevPage');
        var pageInfo = document.getElementById('sourcesPageInfo');
        var nextButton = document.getElementById('sourcesNextPage');
        renderSourcePlatformSelectors(sourceModel);
        if (countElement) {
            countElement.textContent = String(totalCount);
        }
        if (searchInput && document.activeElement !== searchInput) {
            searchInput.value = sourceUiState.search;
        }
        if (statusFilter) {
            statusFilter.innerHTML = '<option value="">' + 'Todos los estados' + '</option>' + '<option value="active">' + 'Activas' + '</option>' + '<option value="inactive">' + 'Inactivas' + '</option>';
            statusFilter.value = sourceUiState.statusFilter;
        }
        if (handleInput && document.activeElement !== handleInput) {
            handleInput.value = sourceUiState.formHandle;
        }
        if (externalIdInput && document.activeElement !== externalIdInput) {
            externalIdInput.value = sourceUiState.formExternalId;
        }
        if (tableBody) {
            if (sources.length === 0) {
                tableBody.innerHTML = '<tr>' + '<td colspan="6">' + '<div class="sources-empty">' + '<strong>' + 'Sin fuentes para mostrar' + '</strong>' + '<span>' + 'Ajusta los filtros o registra una nueva fuente.' + '</span>' + '</div>' + '</td>' + '</tr>';
            } else {
                tableBody.innerHTML = sources.map(renderSourceRow).join('');
            }
        }
        if (pagination) {
            pagination.hidden = false;
        }
        if (previousButton) {
            previousButton.disabled = page <= 1;
        }
        if (pageInfo) {
            pageInfo.textContent = 'Página ' + String(page) + ' de ' + String(totalPages);
        }
        if (nextButton) {
            nextButton.disabled = page >= totalPages;
        }
    }

