        applySourceUiStatePatch(patch);
        try {
            await appsmith.updateModel(getSourceModelPatch());
        } catch (error) {
            console.error('No fue posible actualizar el estado de Fuentes:', error);
        }
    }

    async function reloadSourcesWithPatch(patch) {
        await updateSourceModel(patch);
        appsmith.triggerEvent('onLoadSources');
    }

    function scheduleSourceSearch(value) {
        if (sourceSearchTimer) {
            clearTimeout(sourceSearchTimer);
        }
        sourceSearchTimer = setTimeout(function() {
            sourceSearchTimer = null;
            reloadSourcesWithPatch({
                sourceSearch: String(value || '').trim(),
                sourcePage: 1
            });
        }, 350);
    }

