        var patch = {};
        patch[key] = String(value || '').trim();
        await updateSourceModel(patch);
    }

    async function createManagedSource() {
        var platformInput = document.getElementById('sourcePlatform');
        var handleInput = document.getElementById('sourceHandle');
        var externalIdInput = document.getElementById('sourceExternalId');
        var platform = platformInput ? String(platformInput.value || '').trim() : '';
        var handle = handleInput ? String(handleInput.value || '').trim() : '';
        var externalId = externalIdInput ? String(externalIdInput.value || '').trim() : '';

        await updateSourceModel({
            sourceFormPlatform: platform,
            sourceFormHandle: handle,
            sourceFormExternalId: externalId,
            sourcePage: 1
        });

        appsmith.triggerEvent('onCreateSource');
    }

    async function toggleManagedSource(id) {
        var sourceId = String(id || '').trim();
        if (!sourceId) {
            return;
        }
        var page = getSourcePage();
        initializeSourceUiState();
        var statusFilter = sourceUiState.statusFilter;
        var patch = {
            sourceActionId: sourceId
        };
        if (statusFilter !== '' && getManagedSources().length === 1 && page > 1) {
            patch.sourcePage = page - 1;
        }
        await updateSourceModel(patch);
        appsmith.triggerEvent('onToggleSource');
    }

    async function deleteManagedSource(id) {
        var sourceId = String(id || '').trim();
        if (!sourceId) {
            return;
        }

        var source = getManagedSources().find(function(item) {
            return (item && String(item.id || '') === sourceId);
        });

        var sourceLabel = source
            ? (source.handle || source.external_profile_id || getSourcePlatformName(source.platform))
            : 'esta fuente';

        var confirmed = window.confirm(
            '¿Eliminar ' + String(sourceLabel) + '?'
        );

        if (!confirmed) {
            return;
        }

        var page = getSourcePage();
        var patch = {
            sourceActionId: sourceId
        };

        if (
            getManagedSources().length === 1 &&
            page > 1
        ) {
            patch.sourcePage = page - 1;
        }

        await updateSourceModel(patch);
        appsmith.triggerEvent('onDeleteSource');
    }

    function changeSourcePage(direction) {
        var page = getSourcePage();
        var totalPages = getSourceTotalPages();
        var nextPage = page + Number(direction || 0);
        nextPage = Math.max(
            1,
            Math.min(nextPage, totalPages)
        );

        if (nextPage === page) {
            return;
        }

        reloadSourcesWithPatch({
            sourcePage: nextPage
        });
    }

    function normalizeQueryView(value) {
        var view = String(value || '').trim().toLowerCase();
        if (
            view === 'all' ||
            view === 'sources'
        ) {
            return view;
        }
        return 'constructor';
    }

    function renderQueryNavigation() {
        var view = normalizeQueryView(currentQueryView);
        currentQueryView = view;

        var buttons = document.querySelectorAll(
            '[data-query-view]'
        );

        buttons.forEach(function(button) {
            var buttonView = normalizeQueryView(
                button.getAttribute('data-query-view')
            );

            button.classList.toggle(
                'active',
                buttonView === view
            );

            button.setAttribute(
                'aria-current',
                buttonView === view
                    ? 'page'
                    : 'false'
            );
        });

        var panels = document.querySelectorAll(
            '[data-query-view-panel]'
        );

        panels.forEach(function(panel) {
            var panelView = normalizeQueryView(
                panel.getAttribute(
                    'data-query-view-panel'
                )
            );

            var active =
                panelView === view;

            panel.classList.toggle(
                'active',
                active
            );

            panel.hidden = !active;
        });

        if (view === 'constructor') {
            renderCurrentView();
            return;
        }

        if (view === 'all') {
            renderLibrary();
            return;
        }

        if (view === 'sources') {
            renderSourcesManagement();
        }
    }

    function setQueryView(value) {
        var previousView = currentQueryView;

        currentQueryView =
            normalizeQueryView(value);

        renderQueryNavigation();

        if (
            currentQueryView === 'sources' &&
            previousView !== currentQueryView
        ) {
            appsmith.triggerEvent(
                'onLoadSources'
            );
        }
    }

    function getMode() {
        if (
            currentMode !== 'manual' &&
            currentMode !== 'ai'
        ) {
            return 'home';
        }

        return currentMode;
    }

    function getStep() {
        if (
            isNaN(currentStep) ||
            currentStep < 0
        ) {
            return 0;
        }

        if (currentStep > 4) {
            return 4;
        }

        return currentStep;
    }

    function getPageSize() {
        var value = parseInt(
            getModel().queries_page_size || 3,
            10
        );

        if (
            isNaN(value) ||
            value < 1
        ) {
            return 3;
        }

        return value;
    }

    function getMaxGroups() {
        var value = parseInt(
            getModel().query_max_groups || 3,
            10
        );

        if (
            isNaN(value) ||
            value < 1
        ) {
            return 3;
        }

        return value;
    }

    function getTotalPages() {
        var queries = getQueries();
        var pageSize = getPageSize();

        return Math.max(
            1,
            Math.ceil(
                queries.length /
                pageSize
            )
        );
    }

    function clampPage() {
        var totalPages = getTotalPages();

        if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        if (currentPage < 1) {
            currentPage = 1;
        }
    }

    function quoteTerm(term) {
        return (
            '"' +
            String(term)
                .replace(
                    /\\/g,
                    '\\\\'
                )
                .replace(
                    /"/g,
                    '\\"'
                ) +
            '"'
        );
    }

    function buildGroupFormula(group) {
        if (
            !group ||
            group.include.length === 0
        ) {
            return '';
        }

        var includeFormula =
            group.include
                .map(quoteTerm)
                .join(' OR ');

        if (
            group.include.length > 1
        ) {
            includeFormula =
                '(' +
                includeFormula +
                ')';
        }

        var parts = [
            includeFormula
        ];

        group.and.forEach(
            function(term) {
                parts.push(
                    'AND ' +
                    quoteTerm(term)
                );
            }
        );

        group.and_not.forEach(
            function(term) {
                parts.push(
                    'AND NOT ' +
                    quoteTerm(term)
                );
            }
        );

        return parts.join(' ');
    }

    function buildFormula() {
        var formulas =
            groups
                .map(buildGroupFormula)
                .filter(
                    function(formula) {
                        return (
                            formula !== ''
                        );
                    }
                );

        if (
            formulas.length === 0
        ) {
            return '';
        }

        if (
            formulas.length === 1
        ) {
            return formulas[0];
        }

        return formulas
            .map(
                function(formula) {
                    return (
                        '(' +
                        formula +
                        ')'
                    );
                }
            )
            .join(' OR ');
    }

    function getTotalTerms() {
        return groups.reduce(
            function(total, group) {
                return (
                    total +
                    group.include.length +
                    group.and.length +
                    group.and_not.length
                );
            },
            0
        );
    }

    function hasValidManualRules() {
        if (groups.length === 0) {
            return false;
        }

        return groups.every(
            function(group) {
                return (
                    group.include.length > 0
                );
            }
        );
    }

