    function getDrawerLiveStreams(model) {
        var drawerModel = model || getModel();
        var source = asArray(
            drawerModel.drawerLiveStreams ||
            drawerModel.liveStreams ||
            []
        );

        var targets = asArray(drawerModel.targets);

        if (!targets.length || !source.length) {
            return [];
        }

        function normalizeHandle(value) {
            return String(value || '')
                .trim()
                .replace(/^@/, '')
                .toLowerCase();
        }

        function isLive(stream) {
            var status = String(
                stream && (
                    stream.status ||
                    stream.live_status ||
                    stream.stream_status ||
                    ''
                ) || ''
            ).trim().toLowerCase();

            return (
                status === 'live' ||
                status === 'started' ||
                status === 'streaming' ||
                toBoolean(stream && stream.is_live) ||
                toBoolean(stream && stream.live)
            );
        }

        return source.filter(function(stream) {
            if (!stream || !isLive(stream)) {
                return false;
            }

            var streamTargetId = String(
                stream.target_id ||
                stream.targetId ||
                ''
            ).trim();

            var streamPlatform = String(
                stream.platform ||
                ''
            ).trim().toLowerCase();

            var owner = stream.owner && typeof stream.owner === 'object'
                ? stream.owner
                : {};

            var streamHandle = normalizeHandle(
                stream.handle ||
                stream.username ||
                owner.username ||
                ''
            );

            return targets.some(function(target) {
                if (!target) {
                    return false;
                }

                var targetId = String(target.id || '').trim();
                if (
                    streamTargetId &&
                    targetId &&
                    streamTargetId === targetId
                ) {
                    return true;
                }

                var targetPlatform = String(
                    target.platform || ''
                ).trim().toLowerCase();

                var targetHandle = normalizeHandle(
                    target.handle || ''
                );

                return (
                    streamPlatform &&
                    targetPlatform &&
                    streamPlatform === targetPlatform &&
                    streamHandle &&
                    targetHandle &&
                    streamHandle === targetHandle
                );
            });
        });
    }

    function getDrawerLiveStreamAvatar(stream, posts) {
        var owner = stream && stream.owner && typeof stream.owner === 'object'
            ? stream.owner
            : {};

        var direct = safeDrawerUrl(
            stream && (
                stream.avatar_url ||
                stream.profile_avatar_url ||
                stream.profile_pic_url ||
                stream.owner_avatar_url
            ) ||
            owner.avatar_url ||
            owner.profile_pic_url
        );

        if (direct) {
            return direct;
        }

        var streamPlatform = String(
            stream && stream.platform || ''
        ).trim().toLowerCase();

        var streamHandle = String(
            stream && (
                stream.handle ||
                stream.username
            ) ||
            owner.username ||
            ''
        ).trim().replace(/^@/, '').toLowerCase();

        var profiles = getDrawerProfiles(posts);

        for (var index = 0; index < profiles.length; index += 1) {
            var profile = profiles[index];
            var profilePlatform = String(profile.platform || '').trim().toLowerCase();
            var profileHandle = String(profile.handle || '').trim().replace(/^@/, '').toLowerCase();

            if (
                streamPlatform === profilePlatform &&
                streamHandle &&
                profileHandle &&
                streamHandle === profileHandle
            ) {
                return profile.avatarUrl || '';
            }
        }

        return '';
    }

    function formatDrawerDateTime(value) {
        if (!value) {
            return '—';
        }
        try {
            return new Intl.DateTimeFormat('es-MX', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            }).format(new Date(value));
        } catch (error) {
            return '—';
        }
    }

    function formatDrawerMetric(value) {
        if (value === null || value === undefined || value === '') {
            return '—';
        }
        var number = Number(value);
        if (!isFinite(number)) {
            return '—';
        }
        try {
            return new Intl.NumberFormat('es-MX').format(number);
        } catch (error) {
            return String(number);
        }
    }

    function formatDrawerDecimal(value, digits) {
        if (value === null || value === undefined || !isFinite(Number(value))) {
            return '—';
        }
        try {
            return new Intl.NumberFormat('es-MX', {
                minimumFractionDigits: digits || 0,
                maximumFractionDigits: digits || 0
            }).format(Number(value));
        } catch (error) {
            return String(value);
        }
    }

    function formatDrawerPercent(value) {
        if (value === null || value === undefined || !isFinite(Number(value))) {
            return '—';
        }
        return formatDrawerDecimal(Number(value), 1) + '%';
    }

    function safeDrawerUrl(value) {
        var url = String(value || '').trim();
        return /^https?:\/\//i.test(url) ? url : '';
    }

    function drawerBoolean(value) {
        if (value === true || value === 'true') {
            return true;
        }
        if (value === false || value === 'false') {
            return false;
        }
        return null;
    }

    function drawerNumber(value) {
        if (value === null || value === undefined || value === '') {
            return null;
        }
        var number = Number(value);
        return isFinite(number) ? number : null;
    }

    function drawerSum(posts, field) {
        var hasValue = false;
        var total = 0;
        posts.forEach(function(post) {
            var value = drawerNumber(post && post[field]);
            if (value === null) {
                return;
            }
            hasValue = true;
            total += value;
        });
        return hasValue ? total : null;
    }

    function drawerAverage(values) {
        var valid = values.filter(function(value) {
            return value !== null && value !== undefined && isFinite(Number(value));
        });
        if (!valid.length) {
            return null;
        }
        return valid.reduce(function(sum, value) {
            return sum + Number(value);
        }, 0) / valid.length;
    }

    function getDrawerNow() {
        return new Date();
    }

    function getDrawerRangeBounds() {
        var now = getDrawerNow();
        var end = now;
        var start = null;

        if (drawerState.range === '12h') {
            start = new Date(now.getTime() - 12 * 60 * 60 * 1000);
        } else if (drawerState.range === '24h') {
            start = new Date(now.getTime() - 24 * 60 * 60 * 1000);
        } else if (drawerState.range === '7d') {
            start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        } else if (drawerState.range === '30d') {
            start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        } else if (drawerState.range === 'custom') {
            var customStart = drawerState.customStart ? new Date(drawerState.customStart) : null;
            var customEnd = drawerState.customEnd ? new Date(drawerState.customEnd) : null;
            start = customStart && !isNaN(customStart.getTime()) ? customStart : null;
            end = customEnd && !isNaN(customEnd.getTime()) ? customEnd : now;
        } else if (drawerState.range === 'all') {
            start = null;
            end = null;
        }

        return { start: start, end: end };
    }

    function getFilteredDrawerPosts(posts) {
        var source = asArray(posts);
        var bounds = getDrawerRangeBounds();

        if (drawerState.range === 'all') {
            return source.slice();
        }

        return source.filter(function(post) {
            if (!post || !post.published_at) {
                return false;
            }
            var published = new Date(post.published_at);
            if (isNaN(published.getTime())) {
                return false;
            }
            if (bounds.start && published.getTime() < bounds.start.getTime()) {
                return false;
            }
            if (bounds.end && published.getTime() > bounds.end.getTime()) {
                return false;
            }
            return true;
        });
    }

    function getFilteredDrawerActors(actors) {
        var source = asArray(actors);
        var bounds = getDrawerRangeBounds();

        if (drawerState.range === 'all') {
            return source.slice();
        }

        return source.filter(function(actor) {
            if (!actor || !actor.published_at) {
                return false;
            }

            var published = new Date(actor.published_at);

            if (isNaN(published.getTime())) {
                return false;
            }

            if (
                bounds.start &&
                published.getTime() < bounds.start.getTime()
            ) {
                return false;
            }

            if (
                bounds.end &&
                published.getTime() > bounds.end.getTime()
            ) {
                return false;
            }

            return true;
        });
    }

    function isDrawerWebMention(event) {
        return String(
            event && event.event_type || ''
        ).trim() === 'web_mention';
    }

    function getDrawerUniqueWebMentions(actors) {
        var seen = {};

        return asArray(actors)
            .filter(isDrawerWebMention)
            .filter(function(event) {
                if (!event) {
                    return false;
                }

                var sourceUrl = String(
                    event.source_url ||
                    event.actor_url ||
                    ''
                ).trim();

                var eventId = String(
                    event.event_id ||
                    ''
                ).trim();

                var sourceName = String(
                    event.source_domain ||
                    event.source_name ||
                    event.actor_name ||
                    ''
                ).trim();

                var publishedAt = String(
                    event.published_at ||
                    ''
                ).trim();

                var contentText = String(
                    event.content_text ||
                    ''
                ).trim();

                var key = sourceUrl
                    ? 'url|' + sourceUrl.toLowerCase()
                    : eventId
                        ? 'id|' + eventId
                        : 'fallback|' +
                            sourceName.toLowerCase() +
                            '|' + publishedAt +
                            '|' + contentText.slice(0, 240).toLowerCase();

                if (seen[key]) {
                    return false;
                }

                seen[key] = true;
                return true;
            });
    }

    function getSortedDrawerFeed(posts, webMentions) {
        var feed = [];

        asArray(posts).forEach(function(post) {
            feed.push({
                kind: 'social',
                data: post,
                published_at: post && post.published_at || null,
                interactions: getDrawerInteractionTotal(post)
            });
        });

        asArray(webMentions).forEach(function(mention) {
            feed.push({
                kind: 'web',
                data: mention,
                published_at: mention && mention.published_at || null,
                interactions: null
            });
        });

        feed.sort(function(a, b) {
            if (drawerState.feedSort === 'interaction') {
                var interactionA = a.interactions === null ? -1 : a.interactions;
                var interactionB = b.interactions === null ? -1 : b.interactions;

                if (interactionA !== interactionB) {
                    return interactionB - interactionA;
                }
            }

            var timeA = a && a.published_at
                ? new Date(a.published_at).getTime()
                : 0;

            var timeB = b && b.published_at
                ? new Date(b.published_at).getTime()
                : 0;

            if (isNaN(timeA)) {
                timeA = 0;
            }

            if (isNaN(timeB)) {
                timeB = 0;
            }

            return timeB - timeA;
        });

        return feed;
    }

    function getDrawerInteractionTotal(post) {
        var fields = ['likes_count', 'platform_comments_count', 'shares_count'];
        var total = 0;
        var hasValue = false;
        fields.forEach(function(field) {
            var value = drawerNumber(post && post[field]);
            if (value === null) {
                return;
            }
            hasValue = true;
            total += value;
        });
        return hasValue ? total : null;
    }

    function getSortedDrawerPosts(posts) {
        var sorted = asArray(posts).slice();
        if (drawerState.feedSort === 'interaction') {
            sorted.sort(function(a, b) {
                var totalA = getDrawerInteractionTotal(a);
                var totalB = getDrawerInteractionTotal(b);
                var safeA = totalA === null ? -1 : totalA;
                var safeB = totalB === null ? -1 : totalB;
                if (safeA !== safeB) {
                    return safeB - safeA;
                }
                var timeA = a && a.published_at ? new Date(a.published_at).getTime() : 0;
                var timeB = b && b.published_at ? new Date(b.published_at).getTime() : 0;
                return timeB - timeA;
            });
            return sorted;
        }
        sorted.sort(function(a, b) {
            var timeA = a && a.published_at ? new Date(a.published_at).getTime() : 0;
            var timeB = b && b.published_at ? new Date(b.published_at).getTime() : 0;
            if (isNaN(timeA)) {
                timeA = 0;
            }
            if (isNaN(timeB)) {
                timeB = 0;
            }
            return timeB - timeA;
        });
        return sorted;
    }

    function formatDrawerRangeMoment(value) {
        if (!value) {
            return '—';
        }
        try {
            return new Intl.DateTimeFormat('es-MX', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            }).format(new Date(value));
        } catch (error) {
            return '—';
        }
    }

    function getDrawerRangeLabel() {
        var bounds = getDrawerRangeBounds();
        if (drawerState.range === 'all') {
            return 'Todo el histórico disponible';
        }
        if (!bounds.start || !bounds.end) {
            return 'Rango personalizado';
        }
        return formatDrawerRangeMoment(bounds.start) + ' – ' + formatDrawerRangeMoment(bounds.end);
    }

    function toDrawerLocalInputValue(value) {
        var date = value instanceof Date ? value : new Date(value);
        if (!date || isNaN(date.getTime())) {
            return '';
        }
        var pad = function(number) {
            return String(number).padStart(2, '0');
        };
        return date.getFullYear() + '-' +
            pad(date.getMonth() + 1) + '-' +
            pad(date.getDate()) + 'T' +
            pad(date.getHours()) + ':' +
            pad(date.getMinutes());
    }

    function initializeDrawerCustomRangeInputs() {
        var startInput = document.getElementById('queryDrawerRangeStart');
        var endInput = document.getElementById('queryDrawerRangeEnd');
        var end = getDrawerNow();
        var start = new Date(end.getTime() - 12 * 60 * 60 * 1000);

        if (!drawerState.customStart) {
            drawerState.customStart = start.toISOString();
        }
        if (!drawerState.customEnd) {
            drawerState.customEnd = end.toISOString();
        }
        if (startInput) {
            startInput.value = toDrawerLocalInputValue(drawerState.customStart || start);
        }
        if (endInput) {
            endInput.value = toDrawerLocalInputValue(drawerState.customEnd || end);
        }
    }

    function updateDrawerRangeUi(posts, webMentions) {
        var rangeText = document.getElementById('queryDrawerRangeText');
        var rangeCount = document.getElementById('queryDrawerRangeCount');
        var rangeCaption = document.getElementById('queryDrawerRangeCaption');
        var customRange = document.getElementById('queryDrawerCustomRange');
        var socialCount = asArray(posts).length;
        var webCount = asArray(webMentions).length;
        var totalCount = socialCount + webCount;

        document.querySelectorAll('[data-drawer-range]').forEach(function(button) {
            button.classList.toggle('active', button.getAttribute('data-drawer-range') === drawerState.range);
        });

        if (rangeText) {
            rangeText.textContent = getDrawerRangeLabel();
        }
        if (rangeCount) {
            rangeCount.textContent =
                String(totalCount) +
                (totalCount === 1 ? ' resultado' : ' resultados');
        }
        if (rangeCaption) {
            rangeCaption.textContent = drawerState.range === 'all' ? 'Sin filtro temporal' : 'Basado en published_at';
        }
        if (customRange) {
            customRange.hidden = drawerState.range !== 'custom';
        }
