    function getDrawerMedia(post) {
        return asArray(post && post.media)
            .filter(function(media) {
                return media && Boolean(safeDrawerUrl(media.media_url) || safeDrawerUrl(media.preview_url));
            })
            .sort(function(a, b) {
                return Number(a.media_index || 0) - Number(b.media_index || 0);
            });
    }

    function getDrawerProfileName(post) {
        var displayName = String(post && post.profile_display_name || '').trim();
        if (displayName) {
            return displayName;
        }
        var username = String(post && post.profile_username || post && post.handle || '').trim();
        return username ? username.replace(/^@/, '') : 'Perfil';
    }

    function getDrawerProfileUsername(post) {
        var username = String(post && post.profile_username || post && post.handle || '').trim();
        return username ? '@' + username.replace(/^@/, '') : '';
    }

    function getDrawerAvatarUrl(post) {
        return safeDrawerUrl(post && post.profile_avatar_url);
    }

    function getDrawerInitials(value) {
        var words = String(value || '').trim().split(/\s+/).filter(Boolean);
        if (!words.length) {
            return '•';
        }
        if (words.length === 1) {
            return words[0].slice(0, 2).toUpperCase();
        }
        return (words[0].charAt(0) + words[1].charAt(0)).toUpperCase();
    }

    function renderDrawerAvatar(url, label, sizeClass) {
        var safeUrl = safeDrawerUrl(url);
        var className = 'drawer-avatar ' + String(sizeClass || 'drawer-avatar-md');
        return (
            '<span class="' + escapeHtml(className) + '">' +
                '<span class="drawer-avatar-fallback">' + escapeHtml(getDrawerInitials(label)) + '</span>' +
                (safeUrl
                    ? '<img src="' + escapeHtml(safeUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\'">'
                    : '') +
            '</span>'
        );
    }

    function renderDrawerVerified(value) {
        return drawerBoolean(value) === true
            ? '<span class="drawer-verified" title="Perfil verificado">✓</span>'
            : '';
    }

    function getDrawerLatestObservedAt(posts) {
        var latest = null;
        posts.forEach(function(post) {
            var candidate = post && (
                post.metrics_last_observed_at ||
                post.metrics_fetched_at ||
                post.scraped_at ||
                post.last_confirmed_at ||
                post.matched_at
            );
            if (!candidate) {
                return;
            }
            var time = new Date(candidate).getTime();
            if (!isNaN(time) && (latest === null || time > latest)) {
                latest = time;
            }
        });
        return latest === null ? null : new Date(latest).toISOString();
    }

    function getDrawerPlatformCounts(posts, webMentions) {
        var counts = {};

        asArray(posts).forEach(function(post) {
            var platform = String(post && post.platform || '').trim().toLowerCase() || 'sin_plataforma';
            counts[platform] = (counts[platform] || 0) + 1;
        });

        var webCount = asArray(webMentions).length;

        if (webCount > 0) {
            counts.web = (counts.web || 0) + webCount;
        }

        var preferredOrder = ['facebook', 'instagram', 'threads', 'web'];

        return Object.keys(counts)
            .sort(function(a, b) {
                var indexA = preferredOrder.indexOf(a);
                var indexB = preferredOrder.indexOf(b);
                if (indexA === -1 && indexB === -1) {
                    return a.localeCompare(b, 'es', { sensitivity: 'base' });
                }
                if (indexA === -1) {
                    return 1;
                }
                if (indexB === -1) {
                    return -1;
                }
                return indexA - indexB;
            })
            .map(function(platform) {
                return { platform: platform, count: counts[platform] };
            });
    }

    function getDrawerLatestResultAt(posts, webMentions) {
        var latestValue = getDrawerLatestObservedAt(
            asArray(posts)
        );

        var latestTime = latestValue
            ? new Date(latestValue).getTime()
            : null;

        asArray(webMentions).forEach(function(mention) {
            var candidate = mention && mention.published_at;

            if (!candidate) {
                return;
            }

            var time = new Date(candidate).getTime();

            if (
                !isNaN(time) &&
                (
                    latestTime === null ||
                    time > latestTime
                )
            ) {
                latestTime = time;
            }
        });

        return latestTime === null
            ? null
            : new Date(latestTime).toISOString();
    }

