    function openPostExternally(url) {
        var normalized = String(url || '').trim();
        if (!/^https?:\/\//i.test(normalized)) {
            return;
        }
        try {
            appsmith.triggerEvent('onOpenPost', { url: normalized });
        } catch (error) {
            console.error('No fue posible abrir la publicación:', error);
        }
    }

    function getDrawerSummary(posts) {
        var likes = drawerSum(posts, 'likes_count');
        var comments = drawerSum(posts, 'platform_comments_count');
        var shares = drawerSum(posts, 'shares_count');
        var views = drawerSum(posts, 'views_count');
        var storedComments = drawerSum(posts, 'stored_comments_count');
        var interactions = 0;
        var interactionsAvailable = false;

        posts.forEach(function(post) {
            var total = getDrawerInteractionTotal(post);
            if (total === null) {
                return;
            }
            interactionsAvailable = true;
            interactions += total;
        });

        return {
            posts: posts.length,
            likes: likes,
            comments: comments,
            shares: shares,
            views: views,
            storedComments: storedComments,
            interactions: interactionsAvailable ? interactions : null
        };
    }

    function getDrawerMetricCoverage(posts) {
        var metrics = [
            { key: 'likes_count', label: 'Me gusta' },
            { key: 'platform_comments_count', label: 'Comentarios' },
            { key: 'shares_count', label: 'Compartidos' },
            { key: 'views_count', label: 'Vistas' },
            { key: 'stored_comments_count', label: 'Comentarios guardados' }
        ];
        return metrics.map(function(metric) {
            var count = posts.filter(function(post) {
                return drawerNumber(post && post[metric.key]) !== null;
            }).length;
            return {
                key: metric.key,
                label: metric.label,
                count: count,
                percent: posts.length ? (count / posts.length) * 100 : 0
            };
        });
    }

    function getDrawerPostTypes(posts) {
        var counts = {};
        posts.forEach(function(post) {
            var type = String(post && post.post_type || 'sin_tipo').trim().toLowerCase() || 'sin_tipo';
            counts[type] = (counts[type] || 0) + 1;
        });
        return Object.keys(counts)
            .map(function(type) {
                return {
                    key: type,
                    label: type === 'sin_tipo' ? 'Sin tipo' : type.charAt(0).toUpperCase() + type.slice(1),
                    count: counts[type]
                };
            })
            .sort(function(a, b) {
                return b.count - a.count;
            });
    }

    function normalizeDrawerWord(value) {
        var text = String(value || '').toLowerCase();
        try {
            text = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        } catch (error) {
        }
        return text;
    }

    function getDrawerTerms(posts) {
        var stopWords = {
            para: true, pero: true, como: true, este: true, esta: true, estos: true, estas: true,
            desde: true, hasta: true, entre: true, sobre: true, todo: true, toda: true, todos: true,
            todas: true, una: true, unas: true, uno: true, unos: true, del: true, las: true, los: true,
            con: true, por: true, que: true, sus: true, son: true, fue: true, han: true, hay: true,
            muy: true, mas: true, sin: true, nuestro: true, nuestra: true, nuestros: true, nuestras: true,
            cada: true, donde: true, cuando: true, quien: true, quienes: true, tambien: true, hacia: true,
            tras: true, mediante: true, porque: true, esto: true, al: true, el: true, la: true,
            de: true, en: true, y: true, o: true, a: true, se: true, es: true
        };
        var words = {};
        var hashtags = {};

        posts.forEach(function(post) {
            var text = String(post && post.content_text || '');
            var hashtagMatches = text.match(/#[A-Za-zÀ-ÿ0-9_]+/g) || [];
            hashtagMatches.forEach(function(tag) {
                var key = tag.toLowerCase();
                if (!hashtags[key]) {
                    hashtags[key] = { label: tag, count: 0 };
                }
                hashtags[key].count += 1;
            });

            var plain = normalizeDrawerWord(text)
                .replace(/https?:\/\/\S+/g, ' ')
                .replace(/@[A-Za-z0-9_.-]+/g, ' ')
                .replace(/#[A-Za-zÀ-ÿ0-9_]+/g, ' ')
                .replace(/[^a-z0-9ñ]+/g, ' ');

            plain.split(/\s+/).forEach(function(word) {
                if (word.length < 4 || stopWords[word]) {
                    return;
                }
                words[word] = (words[word] || 0) + 1;
            });
        });

        return {
            terms: Object.keys(words)
                .map(function(word) { return { label: word, count: words[word] }; })
                .sort(function(a, b) {
                    return b.count - a.count || a.label.localeCompare(b.label, 'es');
                })
                .slice(0, 18),
            hashtags: Object.keys(hashtags)
                .map(function(key) { return hashtags[key]; })
                .sort(function(a, b) { return b.count - a.count; })
                .slice(0, 18)
        };
    }

    function getDrawerActivity(posts) {
        var byDay = {};
        var byHour = {};
        posts.forEach(function(post) {
            if (!post || !post.published_at) {
                return;
            }
            var date = new Date(post.published_at);
            if (isNaN(date.getTime())) {
                return;
            }
            var dayKey = date.getFullYear() + '-' +
                String(date.getMonth() + 1).padStart(2, '0') + '-' +
                String(date.getDate()).padStart(2, '0');
            var hour = date.getHours();
            byDay[dayKey] = (byDay[dayKey] || 0) + 1;
            byHour[hour] = (byHour[hour] || 0) + 1;
        });

        var dayItems = Object.keys(byDay).sort().map(function(dayKey) {
            var date = new Date(dayKey + 'T12:00:00');
            var label = dayKey;
            try {
                label = new Intl.DateTimeFormat('es-MX', {
                    day: '2-digit',
                    month: 'short'
                }).format(date);
            } catch (error) {
            }
            return { key: dayKey, label: label, count: byDay[dayKey] };
        });

        var hourItems = Object.keys(byHour)
            .map(function(hour) {
                var hourNumber = Number(hour);
                return {
                    key: hourNumber,
                    label: String(hourNumber).padStart(2, '0') + ':00',
                    count: byHour[hour]
                };
            })
            .sort(function(a, b) { return b.count - a.count; });

        return { days: dayItems, hours: hourItems };
    }

    function getDrawerProfiles(posts) {
        var profilesByKey = {};

        posts.forEach(function(post) {
            var platform = String(post && post.platform || 'sin_plataforma').trim().toLowerCase();
            var username = String(post && post.profile_username || post && post.handle || 'sin_handle').trim();
            var handle = username || 'sin_handle';
            var key = platform + '|' + handle.toLowerCase();

            if (!profilesByKey[key]) {
                profilesByKey[key] = {
                    platform: platform,
                    handle: handle,
                    displayName: String(post && post.profile_display_name || '').trim(),
                    avatarUrl: getDrawerAvatarUrl(post),
                    profileUrl: safeDrawerUrl(post && post.profile_url),
                    locationText: String(post && post.profile_location_text || '').trim(),
                    category: String(post && post.profile_category || '').trim(),
                    isVerified: drawerBoolean(post && post.profile_is_verified),
                    followersCount: drawerNumber(post && post.followers_count),
                    followingCount: drawerNumber(post && post.following_count),
                    profilePostsCount: drawerNumber(post && post.profile_posts_count),
                    profileFirstObservedAt: post && post.profile_first_observed_at || null,
                    profileLastObservedAt: post && post.profile_last_observed_at || null,
                    posts: 0,
                    likes: 0,
                    comments: 0,
                    shares: 0,
                    views: 0,
                    interactions: 0,
                    availableLikes: false,
                    availableComments: false,
                    availableShares: false,
                    availableViews: false,
                    availableInteractions: false,
                    activeDays: {},
                    latestPublishedAt: null
                };
            }

            var group = profilesByKey[key];
            if (!group.displayName && post && post.profile_display_name) {
                group.displayName = String(post.profile_display_name).trim();
            }
            if (!group.avatarUrl) {
                group.avatarUrl = getDrawerAvatarUrl(post);
            }
            if (!group.profileUrl) {
                group.profileUrl = safeDrawerUrl(post && post.profile_url);
            }
            if (!group.locationText && post && post.profile_location_text) {
                group.locationText = String(post.profile_location_text).trim();
            }
            if (!group.category && post && post.profile_category) {
                group.category = String(post.profile_category).trim();
            }
            if (group.isVerified !== true && drawerBoolean(post && post.profile_is_verified) === true) {
                group.isVerified = true;
            }

            [
                ['followers_count', 'followersCount'],
                ['following_count', 'followingCount'],
                ['profile_posts_count', 'profilePostsCount']
            ].forEach(function(mapping) {
                var value = drawerNumber(post && post[mapping[0]]);
                if (value !== null) {
                    group[mapping[1]] = value;
                }
            });

            group.posts += 1;

            [
                ['likes_count', 'likes', 'availableLikes'],
                ['platform_comments_count', 'comments', 'availableComments'],
                ['shares_count', 'shares', 'availableShares'],
                ['views_count', 'views', 'availableViews']
            ].forEach(function(mapping) {
                var value = drawerNumber(post && post[mapping[0]]);
                if (value === null) {
                    return;
                }
                group[mapping[1]] += value;
                group[mapping[2]] = true;
            });

            var interactions = getDrawerInteractionTotal(post);
            if (interactions !== null) {
                group.interactions += interactions;
                group.availableInteractions = true;
            }

            if (post && post.published_at) {
                var published = new Date(post.published_at);
                if (!isNaN(published.getTime())) {
                    var dayKey = published.toISOString().slice(0, 10);
                    group.activeDays[dayKey] = true;
                    if (!group.latestPublishedAt || published.getTime() > new Date(group.latestPublishedAt).getTime()) {
                        group.latestPublishedAt = published.toISOString();
                    }
                }
            }
        });

        return Object.keys(profilesByKey)
            .map(function(key) {
                var group = profilesByKey[key];
                group.activeDayCount = Object.keys(group.activeDays).length;
                group.postsPerActiveDay = group.activeDayCount ? group.posts / group.activeDayCount : null;
                return group;
            })
            .sort(function(a, b) {
                return b.posts - a.posts ||
                    (b.availableInteractions ? b.interactions : -1) -
                    (a.availableInteractions ? a.interactions : -1);
            });
    }


    function getDrawerActorStats(actors) {
        var byKey = {};

        asArray(actors).forEach(function(event) {
            if (!event) {
                return;
            }

            var platform = String(event.platform || 'web').trim().toLowerCase() || 'web';
            var actorId = String(event.actor_id || '').trim();
            var actorName = String(event.actor_name || event.source_name || event.source_domain || actorId || 'Actor sin identificar').trim();
            var key = platform + '|' + (actorId || actorName.toLowerCase());

            if (!byKey[key]) {
                byKey[key] = {
                    key: key,
                    platform: platform,
                    actorId: actorId,
                    actorName: actorName,
                    actorUrl: safeDrawerUrl(event.actor_url || event.source_url),
                    actorAvatarUrl: safeDrawerUrl(
                        event.actor_avatar_url ||
                        event.avatar_url ||
                        event.profile_pic_url ||
                        event.profile_image_url
                    ),
                    actorGender: String(event.actor_gender || '').trim().toUpperCase(),
                    comments: 0,
                    webMentions: 0,
                    events: 0,
                    latestAt: null
                };
            }

            var actor = byKey[key];

            actor.events += 1;

            if (String(event.event_type || '') === 'web_mention') {
                actor.webMentions += 1;
            } else {
                actor.comments += 1;
            }

            if (!actor.actorUrl) {
                actor.actorUrl = safeDrawerUrl(event.actor_url || event.source_url);
            }

            if (!actor.actorAvatarUrl) {
                actor.actorAvatarUrl = safeDrawerUrl(
                    event.actor_avatar_url ||
                    event.avatar_url ||
                    event.profile_pic_url ||
                    event.profile_image_url
                );
            }

            if (!actor.actorGender && event.actor_gender) {
                actor.actorGender = String(event.actor_gender).trim().toUpperCase();
            }

            if (event.published_at) {
                var time = new Date(event.published_at).getTime();
                if (!isNaN(time) && (!actor.latestAt || time > new Date(actor.latestAt).getTime())) {
                    actor.latestAt = new Date(time).toISOString();
                }
            }
        });

        return Object.keys(byKey)
            .map(function(key) {
                return byKey[key];
            })
            .sort(function(a, b) {
                return b.events - a.events ||
                    String(a.actorName).localeCompare(String(b.actorName), 'es', { sensitivity: 'base' });
            });
    }

    function getDrawerGenderSummary(actors) {
        var counts = {
            MALE: 0,
            FEMALE: 0,
            NEUTER: 0,
            UNKNOWN: 0,
            UNAVAILABLE: 0
        };

        asArray(actors).forEach(function(event) {
            var gender = String(event && event.actor_gender || '').trim().toUpperCase();

            if (gender === 'MALE' || gender === 'FEMALE' || gender === 'NEUTER' || gender === 'UNKNOWN') {
                counts[gender] += 1;
            } else {
                counts.UNAVAILABLE += 1;
            }
        });

        return [
            { key: 'MALE', label: 'Masculino', count: counts.MALE },
            { key: 'FEMALE', label: 'Femenino', count: counts.FEMALE },
            { key: 'NEUTER', label: 'Neutro / institución', count: counts.NEUTER },
            { key: 'UNKNOWN', label: 'Desconocido', count: counts.UNKNOWN },
            { key: 'UNAVAILABLE', label: 'Sin dato', count: counts.UNAVAILABLE }
        ];
    }

    function getDrawerCorpusPosts(posts, actors) {
        var corpus = [];

        asArray(posts).forEach(function(post) {
            corpus.push({
                content_text: post && post.content_text || ''
            });
        });

        asArray(actors).forEach(function(actor) {
            corpus.push({
                content_text: actor && actor.content_text || ''
            });
        });

        return corpus;
    }

    function getDrawerRelations(posts, actors) {
        var corpus = getDrawerCorpusPosts(posts, actors);
        var terms = getDrawerTerms(corpus).terms.slice(0, 14);
        var allowed = {};
        var labels = {};

        terms.forEach(function(item) {
            var key = normalizeDrawerWord(item.label);
            allowed[key] = true;
            labels[key] = item.label;
        });

        var pairs = {};

        corpus.forEach(function(item) {
            var normalized = normalizeDrawerWord(item && item.content_text || '')
                .replace(/https?:\/\/\S+/g, ' ')
                .replace(/[^a-z0-9ñ#]+/g, ' ');

            var present = {};

            normalized.split(/\s+/).forEach(function(word) {
                if (allowed[word]) {
                    present[word] = true;
                }
            });

            var keys = Object.keys(present).sort();

            for (var i = 0; i < keys.length; i += 1) {
                for (var j = i + 1; j < keys.length; j += 1) {
                    var pairKey = keys[i] + '||' + keys[j];
                    pairs[pairKey] = (pairs[pairKey] || 0) + 1;
                }
            }
        });

        return Object.keys(pairs)
            .map(function(key) {
                var parts = key.split('||');
                return {
                    source: labels[parts[0]] || parts[0],
                    target: labels[parts[1]] || parts[1],
                    label: (labels[parts[0]] || parts[0]) + ' ↔ ' + (labels[parts[1]] || parts[1]),
                    count: pairs[key]
                };
            })
            .sort(function(a, b) {
                return b.count - a.count || a.label.localeCompare(b.label, 'es');
            })
            .slice(0, 18);
    }

    function getDrawerTimeline(posts, actors) {
        var timestamps = [];

        asArray(posts).forEach(function(post) {
            if (post && post.published_at) {
                var time = new Date(post.published_at).getTime();
                if (!isNaN(time)) {
                    timestamps.push(time);
                }
            }
        });

        asArray(actors).forEach(function(actor) {
            if (actor && actor.published_at) {
                var time = new Date(actor.published_at).getTime();
                if (!isNaN(time)) {
                    timestamps.push(time);
                }
            }
        });

        if (!timestamps.length) {
            return [];
        }

        var bounds = getDrawerRangeBounds();
        var start = bounds.start ? bounds.start.getTime() : Math.min.apply(null, timestamps);
        var end = bounds.end ? bounds.end.getTime() : Math.max.apply(null, timestamps);

        if (end < start) {
            var swap = start;
            start = end;
            end = swap;
        }

        var rangeMs = Math.max(1, end - start);
        var hourMs = 60 * 60 * 1000;
        var dayMs = 24 * hourMs;
        var bucketMs = rangeMs <= 48 * hourMs ? hourMs : dayMs;

        start = Math.floor(start / bucketMs) * bucketMs;
        end = Math.ceil(end / bucketMs) * bucketMs;

        var maxBuckets = bucketMs === hourMs ? 49 : 45;
        var bucketCount = Math.floor((end - start) / bucketMs) + 1;

        if (bucketCount > maxBuckets) {
            bucketMs = Math.ceil((end - start) / (maxBuckets - 1));
            bucketMs = Math.max(dayMs, Math.ceil(bucketMs / dayMs) * dayMs);
            bucketCount = Math.floor((end - start) / bucketMs) + 1;
        }

        var buckets = [];

        for (var cursor = start; cursor <= end && buckets.length < maxBuckets; cursor += bucketMs) {
            var date = new Date(cursor);
            var label;

            try {
                if (bucketMs <= hourMs) {
                    label = new Intl.DateTimeFormat('es-MX', {
                        hour: 'numeric'
                    }).format(date);
                } else {
                    label = new Intl.DateTimeFormat('es-MX', {
                        day: '2-digit',
                        month: 'short'
                    }).format(date);
                }
            } catch (error) {
                label = date.toISOString();
            }

            buckets.push({
                start: cursor,
                end: cursor + bucketMs,
                label: label,
                publications: 0,
                actorEvents: 0,
                interactions: 0,
                views: 0
            });
        }

        function findBucket(time) {
            var index = Math.floor((time - start) / bucketMs);
            return index >= 0 && index < buckets.length ? buckets[index] : null;
        }

        asArray(posts).forEach(function(post) {
            if (!post || !post.published_at) {
                return;
            }

            var time = new Date(post.published_at).getTime();

            if (isNaN(time)) {
                return;
            }

            var bucket = findBucket(time);

            if (!bucket) {
                return;
            }

            bucket.publications += 1;

            var interactions = getDrawerInteractionTotal(post);
            if (interactions !== null) {
                bucket.interactions += interactions;
            }

            var views = drawerNumber(post.views_count);
            if (views !== null) {
                bucket.views += views;
            }
        });

        asArray(actors).forEach(function(actor) {
            if (!actor || !actor.published_at) {
                return;
            }

            var time = new Date(actor.published_at).getTime();

            if (isNaN(time)) {
                return;
            }

            var bucket = findBucket(time);

            if (bucket) {
                bucket.actorEvents += 1;
            }
        });

        return buckets;
    }

    function renderDrawerLineChart(timeline, series) {
        var data = asArray(timeline);
        var seriesList = asArray(series);

        if (!data.length || !seriesList.length) {
            return '<div class="drawer-empty-inline">Sin datos temporales disponibles.</div>';
        }

        var width = 760;
        var height = 250;
        var left = 42;
        var right = 12;
        var top = 14;
        var bottom = 34;
        var innerWidth = width - left - right;
        var innerHeight = height - top - bottom;
        var maxValue = 0;

        seriesList.forEach(function(item) {
            data.forEach(function(row) {
                var value = Number(row[item.key] || 0);
                if (isFinite(value) && value > maxValue) {
                    maxValue = value;
                }
            });
        });

        maxValue = Math.max(1, maxValue);

        var grid = '';
        for (var g = 0; g <= 4; g += 1) {
            var y = top + (innerHeight * g / 4);
            var value = maxValue * (1 - g / 4);
            grid +=
                '<line class="drawer-chart-grid" x1="' + left + '" y1="' + y.toFixed(2) + '" x2="' + (width - right) + '" y2="' + y.toFixed(2) + '"></line>' +
                '<text class="drawer-chart-axis-label" x="' + (left - 7) + '" y="' + (y + 3).toFixed(2) + '" text-anchor="end">' + escapeHtml(formatDrawerMetric(Math.round(value))) + '</text>';
        }

        var xLabels = '';
        var labelEvery = Math.max(1, Math.ceil(data.length / 8));

        data.forEach(function(row, index) {
            if (index % labelEvery !== 0 && index !== data.length - 1) {
                return;
            }
            var x = left + (data.length === 1 ? innerWidth / 2 : innerWidth * index / (data.length - 1));
            xLabels += '<text class="drawer-chart-axis-label" x="' + x.toFixed(2) + '" y="' + (height - 8) + '" text-anchor="middle">' + escapeHtml(row.label) + '</text>';
        });

        var paths = '';

        seriesList.forEach(function(item, seriesIndex) {
            var points = data.map(function(row, index) {
                var x = left + (data.length === 1 ? innerWidth / 2 : innerWidth * index / (data.length - 1));
                var value = Number(row[item.key] || 0);
                var y = top + innerHeight - (Math.max(0, value) / maxValue) * innerHeight;
                return {
                    x: x,
                    y: y
                };
            });

            var className = 'drawer-series-' + (seriesIndex + 1);

            paths += '<polyline class="drawer-chart-series ' + className + '" points="' +
                points.map(function(point) {
                    return point.x.toFixed(2) + ',' + point.y.toFixed(2);
                }).join(' ') +
                '"></polyline>';

            points.forEach(function(point) {
                paths += '<circle class="drawer-chart-dot ' + className + '" cx="' + point.x.toFixed(2) + '" cy="' + point.y.toFixed(2) + '" r="3.2"></circle>';
            });
        });

        var legend = '<div class="drawer-chart-legend">' +
            seriesList.map(function(item, index) {
                return '<span><i class="l' + (index + 1) + '"></i>' + escapeHtml(item.label) + '</span>';
            }).join('') +
            '</div>';

        return (
            '<svg class="drawer-line-chart" viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="Línea de tiempo">' +
                grid +
                xLabels +
                paths +
            '</svg>' +
            legend
        );
    }

    function renderDrawerDonut(items) {
        var source = asArray(items).filter(function(item) {
            return Number(item.count !== undefined ? item.count : item.value || 0) > 0;
        });

        if (!source.length) {
            return '<div class="drawer-empty-inline">Sin datos disponibles.</div>';
        }

        var total = source.reduce(function(sum, item) {
            return sum + Number(item.count !== undefined ? item.count : item.value || 0);
        }, 0);

        var radius = 56;
        var circumference = 2 * Math.PI * radius;
        var offset = 0;

        var circles = source.slice(0, 5).map(function(item, index) {
            var value = Number(item.count !== undefined ? item.count : item.value || 0);
            var fraction = total ? value / total : 0;
            var dash = fraction * circumference;
            var gap = Math.max(0, circumference - dash);
            var circle =
                '<circle class="drawer-donut-segment drawer-series-' + ((index % 4) + 1) + '"' +
                    ' cx="70" cy="70" r="' + radius + '"' +
                    ' stroke-dasharray="' + dash.toFixed(3) + ' ' + gap.toFixed(3) + '"' +
                    ' stroke-dashoffset="' + (-offset).toFixed(3) + '">' +
                '</circle>';
            offset += dash;
            return circle;
        }).join('');

        var legend = source.slice(0, 5).map(function(item, index) {
            var value = Number(item.count !== undefined ? item.count : item.value || 0);
            var percent = total ? (value / total) * 100 : 0;
            return (
                '<div>' +
                    '<i class="l' + ((index % 4) + 1) + '" style="background:' +
                        (index % 4 === 0 ? 'var(--blue)' :
                         index % 4 === 1 ? 'var(--cyan)' :
                         index % 4 === 2 ? 'var(--warning)' :
                         'var(--light-blue)') +
                    '"></i>' +
                    '<span>' + escapeHtml(item.label || item.key || '') + '</span>' +
                    '<strong>' + escapeHtml(formatDrawerPercent(percent)) + '</strong>' +
                '</div>'
            );
        }).join('');

        return (
            '<div class="drawer-donut-wrap">' +
                '<svg class="drawer-donut-svg" viewBox="0 0 140 140" role="img" aria-label="Distribución">' +
                    '<circle class="drawer-donut-track" cx="70" cy="70" r="' + radius + '"></circle>' +
                    circles +
                '</svg>' +
                '<div class="drawer-donut-legend">' + legend + '</div>' +
            '</div>'
        );
    }

    function renderDrawerWordCloud(items) {
        var source = asArray(items)
            .filter(function(item) {
                return (
                    item &&
                    String(item.label || '').trim() !== '' &&
                    Number(item.count || 0) > 0
                );
            });

        if (!source.length) {
            return '<div class="drawer-empty-inline">Sin términos disponibles.</div>';
        }

        var merged = {};

        source.forEach(function(item) {
            var label = String(item.label || '').trim();
            var key = label.toLowerCase();
            var count = Number(item.count || 0);

            if (!merged[key]) {
                merged[key] = {
                    label: label,
                    count: 0
                };
            }

            merged[key].count += count;
        });

        var cloudItems = Object.keys(merged)
            .map(function(key) {
                return merged[key];
            })
            .sort(function(a, b) {
                return (
                    b.count - a.count ||
                    a.label.localeCompare(
                        b.label,
                        'es',
                        {
                            sensitivity: 'base'
                        }
                    )
                );
            })
            .slice(0, 28);

        if (!cloudItems.length) {
            return '<div class="drawer-empty-inline">Sin términos disponibles.</div>';
        }

        var max = Math.max.apply(
            null,
            cloudItems.map(function(item) {
                return Number(item.count || 0);
            })
        ) || 1;

        var min = Math.min.apply(
            null,
            cloudItems.map(function(item) {
                return Number(item.count || 0);
            })
        );

        var layout = [
            { x: 50, y: 49, r: 0 },
            { x: 26, y: 28, r: 0 },
            { x: 73, y: 26, r: 90 },
            { x: 24, y: 68, r: -90 },
            { x: 73, y: 69, r: 0 },
            { x: 50, y: 18, r: 0 },
            { x: 50, y: 82, r: 90 },
            { x: 12, y: 48, r: 0 },
            { x: 88, y: 50, r: -90 },
            { x: 14, y: 18, r: 90 },
            { x: 86, y: 18, r: 0 },
            { x: 14, y: 83, r: 0 },
            { x: 86, y: 83, r: 90 },
            { x: 36, y: 40, r: -90 },
            { x: 65, y: 41, r: 0 },
            { x: 35, y: 59, r: 0 },
            { x: 65, y: 59, r: 90 },
            { x: 34, y: 12, r: 0 },
            { x: 67, y: 12, r: -90 },
            { x: 34, y: 89, r: 90 },
            { x: 67, y: 89, r: 0 },
            { x: 7, y: 32, r: 0 },
            { x: 93, y: 34, r: 90 },
            { x: 7, y: 68, r: -90 },
            { x: 93, y: 67, r: 0 },
            { x: 20, y: 49, r: 90 },
            { x: 80, y: 48, r: 0 },
            { x: 50, y: 94, r: -90 }
        ];

        var palette = [
            'var(--blue-dark)',
            'var(--cyan)',
            'var(--ink)',
            'var(--blue)',
            'var(--warning)',
            'var(--ink-soft)'
        ];

        var countRange = Math.max(
            1,
            max - min
        );

        /*
         * Todas las palabras se desplazan de forma continua.
         * El foco avanza secuencialmente: una sola palabra
         * alcanza máxima nitidez/escala durante cada ventana.
         */
        var focusStepSeconds = 1.72;
        var cycleSeconds = Math.max(
            12,
            cloudItems.length * focusStepSeconds
        );

        return (
            '<div class="drawer-kinetic-cloud"' +
                ' role="img"' +
                ' aria-label="Nube cinética de términos frecuentes de la consulta"' +
            '>' +
                cloudItems.map(function(item, index) {
                    var count = Number(item.count || 0);
                    var normalized = (count - min) / countRange;
                    var prominence = Math.pow(normalized, 0.58);
                    var slot = layout[index % layout.length];
                    var fontSize = 13 + prominence * 43;
                    var labelLength = String(item.label || '').replace(/^#/, '').length;

                    var focusScale = labelLength > 19
                        ? 1.30
                        : labelLength > 14
                            ? 1.48
                            : labelLength > 10
                                ? 1.72
                                : 2.10;

                    var baseScale = index === 0
                        ? 1.04
                        : 0.88 + prominence * 0.14;

                    var restOpacity = index < 5
                        ? 0.48 + prominence * 0.12
                        : 0.28 + prominence * 0.18;

                    var blur = index < 4
                        ? 0.34
                        : 0.58 + (index % 5) * 0.16;

                    var focusDelay = index * focusStepSeconds;
                    var driftDuration = 7.4 + (index % 7) * 0.92 + prominence * 1.25;
                    var driftDelay = -((index * 1.37) % driftDuration);

                    var driftMagnitude = 16 + (index % 6) * 4 + (1 - prominence) * 12;
                    var signX = index % 2 === 0 ? 1 : -1;
                    var signY = index % 3 === 0 ? -1 : 1;

                    var dx1 = Math.round(signX * driftMagnitude * 0.20);
                    var dy1 = Math.round(signY * driftMagnitude * 0.12);
                    var dx2 = Math.round(-signX * driftMagnitude * 0.82);
                    var dy2 = Math.round(signY * driftMagnitude * 0.56);
                    var dx3 = Math.round(signX * driftMagnitude * 0.64);
                    var dy3 = Math.round(-signY * driftMagnitude * 0.74);
                    var dx4 = Math.round(-signX * driftMagnitude * 0.46);
                    var dy4 = Math.round(-signY * driftMagnitude * 0.34);
                    var dx5 = Math.round(signX * driftMagnitude * 0.28);
                    var dy5 = Math.round(signY * driftMagnitude * 0.66);

                    var driftRotate = ((index % 5) - 2) * 0.42;
                    var color = palette[index % palette.length];

                    return (
                        '<span' +
                            ' class="drawer-kinetic-cloud-word-wrap"' +
                            ' data-cloud-primary="' +
                                (index === 0 ? 'true' : 'false') +
                            '"' +
                            ' style="' +
                                '--cloud-left:' + slot.x + '%;' +
                                '--cloud-top:' + slot.y + '%;' +
                                '--cloud-cycle:' + cycleSeconds.toFixed(2) + 's;' +
                                '--cloud-focus-delay:' + focusDelay.toFixed(2) + 's;' +
                                '--cloud-drift-duration:' + driftDuration.toFixed(2) + 's;' +
                                '--cloud-drift-delay:' + driftDelay.toFixed(2) + 's;' +
                                '--cloud-dx1:' + dx1 + 'px;' +
                                '--cloud-dy1:' + dy1 + 'px;' +
                                '--cloud-dx2:' + dx2 + 'px;' +
                                '--cloud-dy2:' + dy2 + 'px;' +
                                '--cloud-dx3:' + dx3 + 'px;' +
                                '--cloud-dy3:' + dy3 + 'px;' +
                                '--cloud-dx4:' + dx4 + 'px;' +
                                '--cloud-dy4:' + dy4 + 'px;' +
                                '--cloud-dx5:' + dx5 + 'px;' +
                                '--cloud-dy5:' + dy5 + 'px;' +
                                '--cloud-drift-rotate-a:' + driftRotate.toFixed(2) + 'deg;' +
                                '--cloud-drift-rotate-b:' + (-driftRotate * 1.4).toFixed(2) + 'deg;' +
                                '--cloud-drift-rotate-c:' + (driftRotate * 1.9).toFixed(2) + 'deg;' +
                                '--cloud-drift-rotate-d:' + (-driftRotate * 0.8).toFixed(2) + 'deg;' +
                            '"' +
                        '>' +
                            '<span' +
                                ' class="drawer-kinetic-cloud-word"' +
                                ' title="' +
                                    escapeHtml(
                                        item.label +
                                        ' · ' +
                                        formatDrawerMetric(count)
                                    ) +
                                '"' +
                                ' style="' +
                                    '--cloud-rotate:' + slot.r + 'deg;' +
                                    '--cloud-size:' + fontSize.toFixed(1) + 'px;' +
                                    '--cloud-color:' + color + ';' +
                                    '--cloud-base-scale:' + baseScale.toFixed(3) + ';' +
                                    '--cloud-focus-scale:' + focusScale.toFixed(3) + ';' +
                                    '--cloud-rest-opacity:' + restOpacity.toFixed(3) + ';' +
                                    '--cloud-rest-blur:' + blur.toFixed(2) + 'px;' +
                                    '--cloud-cycle:' + cycleSeconds.toFixed(2) + 's;' +
                                    '--cloud-focus-delay:' + focusDelay.toFixed(2) + 's;' +
                                '"' +
                            '>' +
                                escapeHtml(item.label) +
                            '</span>' +
                        '</span>'
                    );
                }).join('') +
            '</div>'
        );
    }

    function renderDrawerRelationNetwork(relations) {
        var source = asArray(relations).filter(function(item) {
            return item && item.source && item.target && Number(item.count || 0) > 0;
        }).slice(0, 16);

        if (!source.length) {
            return '<div class="drawer-empty-inline">No hay suficientes relaciones para construir el gráfico.</div>';
        }

        var nodeWeights = {};
        source.forEach(function(item) {
            nodeWeights[item.source] = (nodeWeights[item.source] || 0) + Number(item.count || 0);
            nodeWeights[item.target] = (nodeWeights[item.target] || 0) + Number(item.count || 0);
        });

        var nodeNames = Object.keys(nodeWeights)
            .sort(function(a, b) {
                return nodeWeights[b] - nodeWeights[a] || a.localeCompare(b, 'es');
            })
            .slice(0, 11);

        var allowed = {};
        nodeNames.forEach(function(name) { allowed[name] = true; });

        var edges = source.filter(function(item) {
            return allowed[item.source] && allowed[item.target];
        });

        var width = 760;
        var height = 390;
        var centerX = width / 2;
        var centerY = height / 2;
        var radiusX = 270;
        var radiusY = 132;
        var maxWeight = Math.max.apply(null, nodeNames.map(function(name) {
            return nodeWeights[name];
        })) || 1;
        var maxEdge = Math.max.apply(null, edges.map(function(item) {
            return Number(item.count || 0);
        })) || 1;

        var nodes = {};
        nodeNames.forEach(function(name, index) {
            var x;
            var y;
            if (index === 0) {
                x = centerX;
                y = centerY;
            } else {
                var angle = ((index - 1) / Math.max(1, nodeNames.length - 1)) * Math.PI * 2 - Math.PI / 2;
                x = centerX + Math.cos(angle) * radiusX;
                y = centerY + Math.sin(angle) * radiusY;
            }
            nodes[name] = { x: x, y: y, weight: nodeWeights[name] };
        });

        var edgeHtml = edges.map(function(item, index) {
            var a = nodes[item.source];
            var b = nodes[item.target];
            if (!a || !b) {
                return '';
            }
            var edgeCount = Number(item.count || 0);
            var strokeWidth = 1.2 + (edgeCount / maxEdge) * 4.2;
            return (
                '<g>' +
                    '<line class="drawer-relation-edge" x1="' + a.x.toFixed(2) + '" y1="' + a.y.toFixed(2) + '" x2="' + b.x.toFixed(2) + '" y2="' + b.y.toFixed(2) + '" style="stroke-width:' + strokeWidth.toFixed(2) + 'px;animation-delay:-' + ((index % 7) * .55).toFixed(2) + 's"></line>' +
                    '<text class="drawer-relation-count" x="' + ((a.x + b.x) / 2).toFixed(2) + '" y="' + (((a.y + b.y) / 2) - 4).toFixed(2) + '" text-anchor="middle">' + escapeHtml(formatDrawerMetric(edgeCount)) + '</text>' +
                '</g>'
            );
        }).join('');

        var nodeHtml = nodeNames.map(function(name, index) {
            var node = nodes[name];
            var scale = node.weight / maxWeight;
            var r = 19 + scale * 18;
            var label = name.length > 18 ? name.slice(0, 17) + '…' : name;
            return (
                '<g>' +
                    '<circle class="drawer-relation-node ' + (index === 0 ? 'primary' : '') + '" cx="' + node.x.toFixed(2) + '" cy="' + node.y.toFixed(2) + '" r="' + r.toFixed(2) + '" style="animation-delay:-' + ((index % 5) * .42).toFixed(2) + 's"></circle>' +
                    '<text class="drawer-relation-label" x="' + node.x.toFixed(2) + '" y="' + (node.y + 4).toFixed(2) + '" text-anchor="middle">' + escapeHtml(label) + '</text>' +
                '</g>'
            );
        }).join('');

        return (
            '<div class="drawer-relations-network">' +
                '<svg class="drawer-relations-svg" viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="Red de relaciones entre términos">' +
                    edgeHtml +
                    nodeHtml +
                '</svg>' +
            '</div>'
        );
    }

