            return drawerInegiGeoJsonPromise;
        }

        drawerInegiGeoJsonPromise = fetch(
            'https://gaia.inegi.org.mx/wscatgeo/v2/geo/mgee/'
        )
            .then(function(response) {
                if (!response.ok) {
                    throw new Error('INEGI respondió HTTP ' + response.status);
                }
                return response.json();
            })
            .then(function(data) {
                if (!data || data.type !== 'FeatureCollection' || !Array.isArray(data.features)) {
                    throw new Error('La respuesta de INEGI no es un FeatureCollection válido.');
                }
                drawerInegiGeoJsonCache = data;
                return data;
            })
            .catch(function(error) {
                drawerInegiGeoJsonPromise = null;
                throw error;
            });

        return drawerInegiGeoJsonPromise;
    }

    function getDrawerGeoFeatureCode(feature) {
        var properties = feature && feature.properties || {};
        var raw = String(
            properties.cve_ent ||
            properties.CVE_ENT ||
            properties.cvegeo ||
            properties.CVEGEO ||
            ''
        ).trim();

        return raw.length >= 2 ? raw.slice(0, 2) : raw;
    }

    function getDrawerGeoFeatureName(feature) {
        var properties = feature && feature.properties || {};
        return String(
            properties.nomgeo ||
            properties.NOMGEO ||
            properties.nom_agee ||
            properties.NOM_AGEE ||
            ''
        ).trim();
    }

    function visitDrawerGeoCoordinates(value, visitor) {
        if (!Array.isArray(value)) {
            return;
        }

        if (
            value.length >= 2 &&
            typeof value[0] === 'number' &&
            typeof value[1] === 'number'
        ) {
            visitor(value[0], value[1]);
            return;
        }

        value.forEach(function(child) {
            visitDrawerGeoCoordinates(child, visitor);
        });
    }

    function getDrawerGeoBounds(features) {
        var bounds = {
            minLon: Infinity,
            maxLon: -Infinity,
            minLat: Infinity,
            maxLat: -Infinity
        };

        asArray(features).forEach(function(feature) {
            visitDrawerGeoCoordinates(
                feature && feature.geometry && feature.geometry.coordinates,
                function(lon, lat) {
                    if (!isFinite(lon) || !isFinite(lat)) {
                        return;
                    }
                    bounds.minLon = Math.min(bounds.minLon, lon);
                    bounds.maxLon = Math.max(bounds.maxLon, lon);
                    bounds.minLat = Math.min(bounds.minLat, lat);
                    bounds.maxLat = Math.max(bounds.maxLat, lat);
                }
            );
        });

        if (!isFinite(bounds.minLon) || !isFinite(bounds.maxLon) ||
            !isFinite(bounds.minLat) || !isFinite(bounds.maxLat)) {
            return null;
        }

        return bounds;
    }

    function projectDrawerGeoPoint(lon, lat, bounds, width, height, padding) {
        var lonSpan = Math.max(0.000001, bounds.maxLon - bounds.minLon);
        var latSpan = Math.max(0.000001, bounds.maxLat - bounds.minLat);
        var usableWidth = width - (padding * 2);
        var usableHeight = height - (padding * 2);
        var x = padding + ((lon - bounds.minLon) / lonSpan) * usableWidth;
        var y = padding + ((bounds.maxLat - lat) / latSpan) * usableHeight;

        return { x: x, y: y };
    }

    function getDrawerGeoFeatureBounds(feature) {
        return getDrawerGeoBounds(feature ? [feature] : []);
    }

    function buildDrawerGeoRingPath(ring, bounds, width, height, padding) {
        if (!Array.isArray(ring) || !ring.length) {
            return '';
        }

        return ring.map(function(point, index) {
            if (!Array.isArray(point) || point.length < 2) {
                return '';
            }
            var projected = projectDrawerGeoPoint(
                Number(point[0]),
                Number(point[1]),
                bounds,
                width,
                height,
                padding
            );
            return (index === 0 ? 'M' : 'L') +
                projected.x.toFixed(2) + ' ' +
                projected.y.toFixed(2);
        }).join(' ') + ' Z';
    }

    function buildDrawerGeoGeometryPath(geometry, bounds, width, height, padding) {
        if (!geometry || !Array.isArray(geometry.coordinates)) {
            return '';
        }

        if (geometry.type === 'Polygon') {
            return geometry.coordinates.map(function(ring) {
                return buildDrawerGeoRingPath(ring, bounds, width, height, padding);
            }).join(' ');
        }

        if (geometry.type === 'MultiPolygon') {
            return geometry.coordinates.map(function(polygon) {
                return asArray(polygon).map(function(ring) {
                    return buildDrawerGeoRingPath(ring, bounds, width, height, padding);
                }).join(' ');
            }).join(' ');
        }

        return '';
    }

    function getDrawerWebGeoSummary(webMentions) {
        var catalog = getDrawerMexicoGeoCatalog();
        var byKey = {};
        var matchedMentions = {};

        catalog.forEach(function(location) {
            byKey[location.key] = {
                key: location.key,
                name: location.name,
                cveEnt: location.cveEnt,
                mentions: 0,
                sources: {}
            };
        });

        asArray(webMentions).forEach(function(mention, mentionIndex) {
            if (!mention) {
                return;
            }

            var text = normalizeDrawerGeoText(
                mention.content_text || ''
            );

            if (!text) {
                return;
            }

            var padded = ' ' + text + ' ';
            var matchedAny = false;
            var source = String(
                mention.source_domain ||
                mention.source_name ||
                mention.actor_name ||
                mention.actor_id ||
                'Fuente web'
            ).trim();

            catalog.forEach(function(location) {
                var matched = location.aliases.some(function(alias) {
                    var normalizedAlias = normalizeDrawerGeoText(alias);
                    return normalizedAlias &&
                        padded.indexOf(' ' + normalizedAlias + ' ') !== -1;
                });

                if (!matched) {
                    return;
                }

                matchedAny = true;
                var item = byKey[location.key];
                item.mentions += 1;
                item.sources[source] = (item.sources[source] || 0) + 1;
            });

            if (matchedAny) {
                var mentionKey = String(
                    mention.event_id ||
                    mention.source_url ||
                    mention.actor_url ||
                    ('mention-' + mentionIndex)
                );
                matchedMentions[mentionKey] = true;
            }
        });

        var locations = Object.keys(byKey)
            .map(function(key) {
                var item = byKey[key];
                item.sourceList = Object.keys(item.sources)
                    .map(function(source) {
                        return {
                            name: source,
                            count: item.sources[source]
                        };
                    })
                    .sort(function(a, b) {
                        return b.count - a.count ||
                            String(a.name).localeCompare(
                                String(b.name),
                                'es',
                                { sensitivity: 'base' }
                            );
                    });
                return item;
            })
            .filter(function(item) {
                return item.mentions > 0;
            })
            .sort(function(a, b) {
                return b.mentions - a.mentions ||
                    String(a.name).localeCompare(
                        String(b.name),
                        'es',
                        { sensitivity: 'base' }
                    );
            });

        return {
            locations: locations,
            matchedMentions: Object.keys(matchedMentions).length
        };
    }

    function renderDrawerGeoMap(geoSummary) {
        var locations = geoSummary.locations || [];

        return (
            '<div class="drawer-geo-map" data-drawer-geo-map>' +
                '<div class="drawer-geo-map-loading">' +
                    '<span class="drawer-geo-map-spinner"></span>' +
                    '<div><strong>Cargando cartografía oficial de México</strong><small>INEGI · Marco Geoestadístico</small></div>' +
                '</div>' +
                (!locations.length
                    ? '<div class="drawer-geo-map-no-data"><strong>Sin ubicaciones Web detectadas</strong><span>El mapa se mostrará sin marcadores.</span></div>'
                    : '') +
            '</div>'
        );
    }

    function renderDrawerGeoMapSvg(geoJson, geoSummary) {
        var width = 1000;
        var height = 560;
        var padding = 24;
        var features = asArray(geoJson && geoJson.features).filter(function(feature) {
            return feature && feature.geometry &&
                (feature.geometry.type === 'Polygon' || feature.geometry.type === 'MultiPolygon');
        });
        var bounds = getDrawerGeoBounds(features);

        if (!bounds || !features.length) {
            throw new Error('INEGI no devolvió geometrías estatales utilizables.');
        }

        var locations = geoSummary.locations || [];
        var locationsByCode = {};
        var maxMentions = locations.reduce(function(maximum, item) {
            locationsByCode[String(item.cveEnt || '')] = item;
            return Math.max(maximum, Number(item.mentions || 0));
        }, 0) || 1;

        var statesHtml = features.map(function(feature) {
            var code = getDrawerGeoFeatureCode(feature);
            var name = getDrawerGeoFeatureName(feature) || code || 'Entidad';
            var detected = locationsByCode[code];
            var path = buildDrawerGeoGeometryPath(
                feature.geometry,
                bounds,
                width,
                height,
                padding
            );

            if (!path) {
                return '';
            }

            return (
                '<g class="drawer-geo-state-group' + (detected ? ' detected' : '') + '">' +
                    '<title>' + escapeHtml(
                        detected
                            ? name + ' · ' + String(detected.mentions) +
                                (detected.mentions === 1 ? ' mención Web' : ' menciones Web')
                            : name
                    ) + '</title>' +
                    '<path class="drawer-geo-state' + (detected ? ' detected' : '') + '"' +
                        ' d="' + escapeHtml(path) + '"' +
                        ' fill-rule="evenodd"' +
                        ' data-geo-code="' + escapeHtml(code) + '"></path>' +
                '</g>'
            );
        }).join('');

        var markersHtml = features.map(function(feature) {
            var code = getDrawerGeoFeatureCode(feature);
            var item = locationsByCode[code];

            if (!item) {
                return '';
            }

            var featureBounds = getDrawerGeoFeatureBounds(feature);
            if (!featureBounds) {
                return '';
            }

            var center = projectDrawerGeoPoint(
                (featureBounds.minLon + featureBounds.maxLon) / 2,
                (featureBounds.minLat + featureBounds.maxLat) / 2,
                bounds,
                width,
                height,
                padding
            );
            var ratio = Number(item.mentions || 0) / maxMentions;
            var radius = 12 + (ratio * 10);
            var fontSize = radius >= 18 ? 10 : 8.5;
            var shortName = String(item.name || '').length > 15
                ? String(item.name || '').slice(0, 14) + '…'
                : String(item.name || '');

            return (
                '<g class="drawer-geo-svg-marker" transform="translate(' +
                    center.x.toFixed(2) + ' ' + center.y.toFixed(2) + ')">' +
                    '<title>' + escapeHtml(
                        item.name + ' · ' + String(item.mentions) +
                        (item.mentions === 1 ? ' mención Web' : ' menciones Web')
                    ) + '</title>' +
                    '<circle r="' + radius.toFixed(2) + '"></circle>' +
                    '<text class="drawer-geo-svg-count" text-anchor="middle" dy="0.35em" style="font-size:' +
                        fontSize.toFixed(1) + 'px">' + escapeHtml(item.mentions) + '</text>' +
                    '<text class="drawer-geo-svg-label" text-anchor="middle" y="' +
                        (radius + 13).toFixed(2) + '">' + escapeHtml(shortName) + '</text>' +
                '</g>'
            );
        }).join('');

        return (
            '<svg class="drawer-geo-map-svg-real" viewBox="0 0 ' + width + ' ' + height + '"' +
                ' role="img" aria-label="Mapa geográfico de México por entidad federativa, cartografía del INEGI">' +
                '<rect class="drawer-geo-ocean" x="0" y="0" width="' + width + '" height="' + height + '"></rect>' +
                '<g class="drawer-geo-states">' + statesHtml + '</g>' +
                '<g class="drawer-geo-markers">' + markersHtml + '</g>' +
            '</svg>' +
            '<div class="drawer-geo-map-legend">' +
                '<strong>Menciones Web</strong>' +
                '<span><i class="small"></i> menor actividad</span>' +
                '<span><i class="large"></i> mayor actividad</span>' +
            '</div>' +
            '<div class="drawer-geo-map-caption">Cartografía oficial INEGI · Marco Geoestadístico</div>'
        );
    }

    function hydrateDrawerGeoMap(geoSummary) {
        var container = document.querySelector('[data-drawer-geo-map]');

        if (!container) {
            return;
        }

        var renderToken = String(Date.now()) + '-' + Math.random().toString(36).slice(2);
        container.setAttribute('data-geo-render-token', renderToken);

        loadDrawerInegiGeoJson()
            .then(function(geoJson) {
                if (!container.isConnected ||
                    container.getAttribute('data-geo-render-token') !== renderToken) {
                    return;
                }
                container.innerHTML = renderDrawerGeoMapSvg(geoJson, geoSummary);
            })
            .catch(function(error) {
                if (!container.isConnected ||
                    container.getAttribute('data-geo-render-token') !== renderToken) {
                    return;
                }

                container.innerHTML =
                    '<div class="drawer-geo-map-error">' +
                        '<strong>No fue posible cargar la cartografía oficial del INEGI.</strong>' +
                        '<span>La sección mantiene el ranking y los datos de ubicación Web; el mapa no se sustituye por geometría aproximada.</span>' +
                    '</div>';

                if (typeof console !== 'undefined' && console.warn) {
                    console.warn('CW_Constructor · INEGI GeoJSON:', error);
                }
            });
    }

