                '<article class="query-drawer-kpi-card"><span class="query-drawer-kpi-icon">▤</span><div><small>Resultados</small><strong>' + escapeHtml(formatDrawerMetric(resultCount)) + '</strong><span>' + escapeHtml(String(asArray(posts).length) + ' redes · ' + String(webMentions.length) + ' web') + '</span></div></article>' +
                '<article class="query-drawer-kpi-card"><span class="query-drawer-kpi-icon">◔</span><div><small>Interacciones</small><strong>' + escapeHtml(formatDrawerMetric(summary.interactions)) + '</strong><span>me gusta + comentarios + compartidos</span></div></article>' +
            '</section>' +

            '<div class="drawer-visual-grid">' +
                '<section class="drawer-visual-card">' +
                    '<div class="drawer-visual-head"><div><strong>Línea de tiempo</strong><span>Evolución de actividad · ' + escapeHtml(latestObserved ? 'actualizado ' + formatDrawerDateTime(latestObserved) : 'sin observación') + '</span></div></div>' +
                    '<div class="drawer-visual-body">' +
                        renderDrawerLineChart(timeline, [
                            { key: 'publications', label: 'Publicaciones' },
                            { key: 'actorEvents', label: 'Comentarios / menciones' },
                            { key: 'interactions', label: 'Interacciones' }
                        ]) +
                    '</div>' +
                '</section>' +
                '<section class="drawer-visual-card">' +
                    '<div class="drawer-visual-head"><div><strong>Tipo de contenido</strong><span>Distribución según post_type</span></div></div>' +
                    '<div class="drawer-visual-body">' + renderDrawerDonut(postTypes) + '</div>' +
                '</section>' +
