                '<section class="query-drawer-panel query-drawer-live-mini-panel">' +
                    '<div class="query-drawer-panel-header compact"><div><span class="query-drawer-panel-kicker">ACTORES CLAVE</span><h3>Conversación</h3></div></div>' +
                    '<div class="query-drawer-live-panel-body">' +
                        (topActors.length
                            ? '<div class="drawer-actor-ranking">' +
                                topActors.map(function(actor, index) {
                                    return (
                                        '<div class="drawer-actor-rank-row">' +
                                            '<span class="rank">' + escapeHtml(index + 1) + '</span>' +
                                            renderDrawerAvatar(getDrawerActorAvatar(actor, posts), actor.actorName, 'drawer-avatar-sm') +
                                            '<div class="drawer-actor-rank-main"><strong>' + escapeHtml(actor.actorName) + '</strong><span>' + escapeHtml(formatPlatformLabel(actor.platform)) + '</span></div>' +
                                            '<span class="drawer-actor-rank-count">' + escapeHtml(formatDrawerMetric(actor.events)) + '</span>' +
                                        '</div>'
                                    );
                                }).join('') +
                              '</div>'
                            : '<div class="drawer-empty-inline">Sin comentarios o menciones en el rango.</div>') +
