                '</section>' +
                '<section class="query-drawer-panel query-drawer-live-mini-panel">' +
                    '<div class="query-drawer-panel-header compact"><div><span class="query-drawer-panel-kicker">PALABRAS CLAVE</span><h3>Términos frecuentes</h3></div></div>' +
                    '<div class="query-drawer-live-panel-body">' + renderDrawerChipCloud(terms.terms.slice(0, 12)) + '</div>' +
                '</section>' +
            '</div>';
