    function getDrawerPlatformKey(value) {
        var normalized = String(value || '').trim().toLowerCase();

        if (normalized.indexOf('instagram') !== -1) {
            return 'instagram';
        }
        if (normalized.indexOf('facebook') !== -1) {
            return 'facebook';
        }
        if (normalized.indexOf('tiktok') !== -1) {
            return 'tiktok';
        }
        if (normalized.indexOf('threads') !== -1) {
            return 'threads';
        }
        if (normalized.indexOf('youtube') !== -1) {
            return 'youtube';
        }
        if (normalized.indexOf('x') === 0 || normalized.indexOf('twitter') !== -1) {
            return 'x';
        }

        return normalized
            .replace(/[^a-z0-9_-]+/g, '-')
            .replace(/^-+|-+$/g, '') || 'social';
    }

    function getDrawerPostTypeKey(value) {
        return String(value || '')
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9_-]+/g, '-')
            .replace(/^-+|-+$/g, '') || 'post';
    }

    function getDrawerPlatformActionIcons(platformKey) {
        if (platformKey === 'facebook') {
            return {
                likes: '👍',
                comments: '◯',
                shares: '↗',
                views: '▶'
            };
        }

        if (platformKey === 'tiktok') {
            return {
                likes: '♥',
                comments: '●',
                shares: '↗',
                views: '▶'
            };
        }

        return {
            likes: '♡',
            comments: '◯',
            shares: '↗',
            views: '▶'
        };
    }

    function renderDrawerNativeMetric(icon, label, value) {
        return (
            '<span class="query-drawer-metric native-post-metric" title="' + escapeHtml(label) + '">' +
                '<span class="native-action-icon" aria-hidden="true">' + escapeHtml(icon) + '</span>' +
                '<strong>' + escapeHtml(value) + '</strong>' +
                '<small>' + escapeHtml(label) + '</small>' +
            '</span>'
        );
    }

    function renderDrawerPostHeader(post, platformKey, platformLabel, profileName, profileUsername, published) {
        var postType = String(post && post.post_type || '').trim();

        return (
            '<div class="query-drawer-post-head native-post-head">' +
                '<div class="query-drawer-post-author">' +
                    renderDrawerAvatar(getDrawerAvatarUrl(post), profileName, 'drawer-avatar-md') +
                    '<div class="query-drawer-post-identity">' +
                        '<strong>' + escapeHtml(profileName) + renderDrawerVerified(post && post.profile_is_verified) + '</strong>' +
                        '<span class="native-post-meta">' +
                            '<span class="native-platform-chip native-platform-' + escapeHtml(platformKey) + '">' + escapeHtml(platformLabel || 'Red social') + '</span>' +
                            (profileUsername ? '<span>' + escapeHtml(profileUsername) + '</span>' : '') +
                        '</span>' +
                    '</div>' +
                '</div>' +
                '<div class="native-post-head-side">' +
                    (postType ? '<span class="native-post-type">' + escapeHtml(postType) + '</span>' : '') +
                    '<span class="query-drawer-post-date">' + escapeHtml(published) + '</span>' +
                '</div>' +
            '</div>'
        );
    }

    function renderDrawerPostCopy(post) {
        var content = escapeHtml(post && post.content_text || '').replace(/\r?\n/g, '<br>');

        return (
            '<div class="query-drawer-post-copy native-post-copy">' +
                (content || '<span>Sin texto disponible.</span>') +
            '</div>'
        );
    }

    function getDrawerPostContentHtml(post) {
        return escapeHtml(post && post.content_text || '').replace(/\r?\n/g, '<br>') || '<span>Sin texto disponible.</span>';
    }

    function renderDrawerPostFooter(post, platformKey, postUrl) {
        var icons = getDrawerPlatformActionIcons(platformKey);
        var likes = formatDrawerMetric(post && post.likes_count);
        var comments = formatDrawerMetric(post && post.platform_comments_count);
        var shares = formatDrawerMetric(post && post.shares_count);
        var views = formatDrawerMetric(post && post.views_count);
        var openLabel =
            platformKey === 'instagram'
                ? 'Ver en Instagram ↗'
                : platformKey === 'facebook'
                    ? 'Ver en Facebook ↗'
                    : platformKey === 'tiktok'
