                        : 'Abrir publicación ↗';

        return (
            '<div class="query-drawer-post-footer native-post-footer">' +
                '<div class="query-drawer-post-metrics native-post-actions">' +
                    renderDrawerNativeMetric(icons.likes, 'Me gusta', likes) +
                    renderDrawerNativeMetric(icons.comments, 'Comentarios', comments) +
                    renderDrawerNativeMetric(icons.shares, 'Compartidos', shares) +
                    renderDrawerNativeMetric(icons.views, 'Vistas', views) +
                '</div>' +
                (postUrl
                    ? '<button type="button" class="query-drawer-post-link native-post-open" data-open-post-url="' + escapeHtml(postUrl) + '">' + escapeHtml(openLabel) + '</button>'
                    : '') +
            '</div>'
