    function truncateDrawerWebText(value, maxLength) {
        var text = String(value || '').trim();
        var limit = Number(maxLength || 1200);

        if (!text || text.length <= limit) {
            return text;
        }

        return text.slice(0, limit).trim() + '…';
    }

    function renderDrawerWebMention(mention) {
        var sourceName = String(
            mention && (
                mention.source_name ||
                mention.source_domain ||
                mention.actor_name ||
                mention.actor_id
            ) ||
            'Fuente web'
        ).trim();

        var published = formatDrawerDateTime(
            mention && mention.published_at
        );

        var sourceUrl = safeDrawerUrl(
            mention && (
                mention.source_url ||
                mention.actor_url
            )
        );

        var rawContent = String(
            mention && mention.content_text ||
            ''
        ).trim();

        var lines = rawContent
            .split(/\r?\n/)
            .map(function(line) {
                return String(line || '').trim();
            })
            .filter(Boolean);

        var title = lines.length
            ? lines.shift()
            : sourceName;

        var body = lines.join('\n');

        if (!body && rawContent && rawContent !== title) {
            body = rawContent;
        }

        var safeTitle = escapeHtml(
            truncateDrawerWebText(
                title,
                260
            )
        );

        var safeBody = escapeHtml(
            truncateDrawerWebText(
                body,
                1200
            )
        ).replace(/\r?\n/g, '<br>');

        return (
            '<article class="query-drawer-post native-post-card platform-web">' +
                '<div class="query-drawer-post-head">' +
                    '<div class="query-drawer-post-author">' +
                        renderDrawerAvatar('', sourceName, 'drawer-avatar-md') +
                        '<div class="query-drawer-post-identity">' +
                            '<strong>' + escapeHtml(sourceName) + '</strong>' +
                            '<span>Web · fuente externa</span>' +
                        '</div>' +
                    '</div>' +
                    '<span class="query-drawer-post-date">' + escapeHtml(published) + '</span>' +
                '</div>' +
                '<div class="query-drawer-post-copy">' +
                    '<strong>' + safeTitle + '</strong>' +
                    (safeBody ? '<br><br>' + safeBody : '') +
                '</div>' +
                '<div class="query-drawer-post-footer">' +
                    '<div class="query-drawer-post-metrics">' +
                        '<span class="query-drawer-metric">Tipo <strong>Web</strong></span>' +
                    '</div>' +
                    (sourceUrl
                        ? '<button type="button" class="query-drawer-post-link" data-open-post-url="' + escapeHtml(sourceUrl) + '">Abrir fuente ↗</button>'
                        : '') +
                '</div>' +
            '</article>'
        );
    }

