    function renderStepper(
        mode,
        step
    ) {
        var wizard =
            document.getElementById(
                'constructorWizard'
            );

        if (!wizard) {
            return;
        }

        if (mode === 'home') {
            wizard.hidden = true;
            return;
        }

        wizard.hidden = false;

        setWizardLabels(mode);

        var steps =
            wizard.querySelectorAll(
                '.wizard-step'
            );

        steps.forEach(
            function(stepElement) {
                var stepNumber =
                    parseInt(
                        stepElement.getAttribute(
                            'data-step'
                        ),
                        10
                    );

                stepElement.classList.toggle(
                    'active',
                    stepNumber === step
                );

                stepElement.classList.toggle(
                    'completed',
                    stepNumber < step
                );

                var numberElement =
                    stepElement.querySelector(
                        '.wizard-number'
                    );

                if (numberElement) {
                    numberElement.textContent =
                        stepNumber < step
                            ? '✓'
                            : String(
                                stepNumber
                            );
                }
            }
        );

        var lines =
            wizard.querySelectorAll(
                '.wizard-line'
            );

        lines.forEach(
            function(line, index) {
                line.classList.toggle(
                    'completed',
                    index + 1 < step
                );
            }
        );
    }

    function getOperatorTerms(
        group,
        operator
    ) {
        if (!group) {
            return [];
        }

        if (operator === 'include') {
            return group.include;
        }

        if (operator === 'and') {
            return group.and;
        }

        if (operator === 'and_not') {
            return group.and_not;
        }

        return [];
    }

    function getOperatorChipClass(
        operator
    ) {
        if (operator === 'and') {
            return 'and';
        }

        if (operator === 'and_not') {
            return 'exclude';
        }

        return '';
    }

    function getEmptyTermsText(
        operator
    ) {
        if (operator === 'include') {
            return (
                'Agrega al menos un término para este grupo.'
            );
        }

        if (operator === 'and') {
            return (
                'Sin condiciones obligatorias.'
            );
        }

        return 'Sin exclusiones.';
    }

    function renderTerms(
        group,
        operator
    ) {
        var terms =
            getOperatorTerms(
                group,
                operator
            );

        if (terms.length === 0) {
            return (
                '<span class="manual-empty-terms">' +
                    escapeHtml(
                        getEmptyTermsText(
                            operator
                        )
                    ) +
                '</span>'
            );
        }

        var chipClass =
            getOperatorChipClass(
                operator
            );

        return terms
            .map(
                function(term, index) {
                    return (
                        '<span class="manual-chip' +
                            (
                                chipClass
                                    ? ' ' +
                                        chipClass
                                    : ''
                            ) +
                        '">' +

                            '<span>' +
                                escapeHtml(
                                    term
                                ) +
                            '</span>' +

                            '<button' +
                                ' type="button"' +
                                ' class="manual-chip-remove"' +
                                ' data-remove-term="' +
                                    escapeHtml(
                                        operator
                                    ) +
                                '"' +
                                ' data-group-no="' +
                                    escapeHtml(
                                        group.group_no
                                    ) +
                                '"' +
                                ' data-term-index="' +
                                    escapeHtml(
                                        index
                                    ) +
                                '"' +
                                ' aria-label="Eliminar término"' +
                            '>' +
                                '×' +
                            '</button>' +

                        '</span>'
                    );
                }
            )
            .join('');
    }

