                var model =
                    newModel ||
                    getModel();

                var queriesValue =
                    String(
                        model.queries ||
                        ''
                    );

                var targetsValue =
                    String(
                        model.targets ||
                        ''
                    );

                var modeValue =
                    String(
                        model
                            .constructor_mode ||
                        'home'
                    );

                var stepValue =
                    String(
                        model
                            .constructor_step ||
                        0
                    );

                var groupsValue =
                    String(
                        model
                            .query_groups_json ||
                        '[]'
                    );

                var targetIdsValue =
                    String(
                        model
                            .query_target_ids_json ||
                        '[]'
                    );

                var useWebValue =
                    String(
                        model
                            .query_use_web ||
                        false
                    );

                var aiResponseValue =
                    String(
                        model
                            .ai_response ||
                        ''
                    );

                var aiInstructionValue =
                    String(
                        model
                            .ai_instruction ||
                        ''
                    )
                    .trim();

                var selectedQueryIdValue =
                    String(
                        model
                            .selectedQueryId ||
                        ''
                    );

                if (selectedQueryIdValue.trim() !== '') {
                    var selectedQueryFromModel =
                        asArray(model.queries)
                            .find(function(item) {
                                return (
                                    item &&
                                    String(item.id || '') ===
                                        selectedQueryIdValue.trim()
                                );
                            }) || null;

                    rememberDrawerSelection(
                        selectedQueryIdValue,
                        selectedQueryFromModel &&
                        selectedQueryFromModel.name ||
                        model.selectedQueryName ||
                        drawerSelection.name,
                        selectedQueryFromModel
                    );
                }

                var incomingDrawerPosts =
                    asArray(
                        model.drawerPosts
                    );

                if (incomingDrawerPosts.length > 0) {
                    cacheDrawerPosts(
                        incomingDrawerPosts
                    );
                }

                var incomingDrawerActors =
                    asArray(
                        model.drawerActors
                    );

                if (incomingDrawerActors.length > 0) {
                    cacheDrawerActors(
                        incomingDrawerActors
                    );
                }

                var sourceManagementValue =
                    getSourceManagementSignature(
                        model
                    );

                var drawerPostsValue =
                    serializeDrawerPosts(
                        model
                    );

                var drawerActorsValue =
                    serializeDrawerActors(
                        model
                    );

                if (
                    aiGenerateArmed &&
                    aiRequestPending &&
                    getMode() === 'ai' &&
                    aiInstructionValue ===
                    aiGenerateInstruction
                ) {
                    aiGenerateArmed =
                        false;

                    appsmith.triggerEvent(
                        'onGenerateAI'
                    );
                }

                if (
                    queriesValue !==
                    lastQueriesValue
                ) {
                    var saveConfirmed =
                        false;

                    if (
                        pendingSaveConfirmation
                    ) {
                        var refreshedQueries =
                            asArray(
                                model.queries
                            );

                        saveConfirmed =
                            refreshedQueries.some(
                                function(query) {
                                    var queryId =
                                        String(
                                            query &&
                                            query.id ||
                                            ''
                                        ).trim();

                                    var queryName =
                                        String(
                                            query &&
                                            query.name ||
                                            ''
                                        ).trim();

                                    return (
                                        queryId !== '' &&
                                        queryName ===
                                            pendingSaveConfirmation
                                                .name &&
                                        pendingSaveConfirmation
                                            .existing_ids
                                            .indexOf(
                                                queryId
                                            ) === -1
                                    );
                                }
                            );
                    }

                    lastQueriesValue =
                        queriesValue;

                    currentPage =
                        1;

                    renderLibrary();

                    if (
                        saveConfirmed
                    ) {
                        pendingSaveConfirmation =
                            null;

                        resetConstructor();

                        return;
                    }
                }

                if (
                    selectedQueryIdValue !==
                    lastSelectedQueryIdValue
                ) {
                    lastSelectedQueryIdValue =
                        selectedQueryIdValue;

                    renderLibrary();

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    drawerPostsValue !==
                    lastDrawerPostsValue
                ) {
                    lastDrawerPostsValue =
                        drawerPostsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    drawerActorsValue !==
                    lastDrawerActorsValue
                ) {
                    lastDrawerActorsValue =
                        drawerActorsValue;

                    if (
                        drawerState.open
                    ) {
                        renderQueryDrawer(
                            model
                        );
                    }
                }

                if (
                    sourceManagementValue !==
                    lastSourceManagementValue
                ) {
                    lastSourceManagementValue =
                        sourceManagementValue;

                    if (
                        currentQueryView ===
                        'sources'
                    ) {
                        renderSourcesManagement(
                            model
                        );
                    }
                }

                if (
                    targetsValue !==
                    lastTargetsValue
                ) {
                    lastTargetsValue =
                        targetsValue;

                    if (
                        modeValue === 'manual' &&
                        (
                            stepValue === '2' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        )
                    ) {
                        renderCurrentView();
                    }
                }

                if (
                    groupsValue !==
                    lastGroupsValue
                ) {
                    lastGroupsValue =
                        groupsValue;

                    if (modeValue === 'manual') {
                        loadGroupsFromModel();

                        if (
                            stepValue === '1' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        ) {
                            renderCurrentView();
                        }
                    }
                }

                if (
                    targetIdsValue !==
                        lastTargetIdsValue ||
                    useWebValue !==
                        lastUseWebValue
                ) {
                    lastTargetIdsValue =
                        targetIdsValue;

                    lastUseWebValue =
                        useWebValue;

                    if (modeValue === 'manual') {
                        loadSourcesFromModel();

                        if (
                            stepValue === '2' ||
                            stepValue === '3' ||
                            stepValue === '4'
                        ) {
                            renderCurrentView();
                        }
                    }
                }

                if (
                    aiResponseValue !==
                    lastAiResponseValue
                ) {
                    lastAiResponseValue =
                        aiResponseValue;

                    if (
                        getMode() === 'ai'
                    ) {
                        var aiResponse =
                            asObject(
                                model.ai_response
                            );

                        if (
                            Object.keys(
                                aiResponse
                            ).length > 0 &&
                            (
                                aiResponse.ok === true ||
                                aiResponse
                                    .needs_clarification ===
                                    true
                            )
                        ) {
                            applyAiResponse(
                                aiResponse
                            );
                        }
                    }
                }

                if (
                    modeValue !==
                        lastModeValue ||
                    stepValue !==
                        lastStepValue
                ) {
                    lastModeValue =
                        modeValue;

                    lastStepValue =
                        stepValue;

                    renderCurrentView();
                }
            }
        );
    }
});
